(window.GIM_TS=window.GIM_TS||{})["Nedarim.0"]={"from":0,"a":[["עיקרו של הנדר הוא במה שאדם אוסר דבר (על עצמו או על אדם אחר) כאילו היה זה קרבן. וכשם שחפץ שהוקדש, הריהו נאסר לכל על ידי דיבור של הקדשה, אף בנדר על ידי אמירתו נאסר הדבר לאדם מסויים. הלשון הבסיסית והמפורשת בנדר היא כגון שאומר \"חפץ זה יהיה אסור עלי (או על אחרים) כקרבן\", ובאה המשנה ומוסיפה כי גם \u0003כל כינויי נדרים — כנדרים,\u0004 כלומר, אם אדם נודר נדר ואינו אומר ומפרש את הדבר בלשון קרבן, אלא אומר בלשון אחרת שהיא כינוי לכך, כגון \"קונם\" — הרי אף זה נדר.","\u0003ו\u0004כן כינויי \u0003חרמים — כחרמים,\u0004 שכמו שאם אמר שדבר מסויים יהיה \"חרם למקדש\" הריהו מוקדש בכך, ואם עושהו כחרם לגבי אדם מסויים — הריהו נאסר עליו, כמו כן גם אם אמר זאת בכינוי, כגון \"חרך\" — דינו כחרם. \u0003ו\u0004כינויי \u0003שבועות — כשבועות,\u0004 שאף אם לא אמר במפורש לשון שבועה, אלא השתמש בכינוי אחר לשבועה כגון \"שבותה\" — אף היא שבועה. \u0003ו\u0004כינויי \u0003נזירות — כנזירות,\u0004 שלא רק לשון \"אהיה נזיר\" מחייבת אותו בנזירות אלא גם כינוי כמו \"אהיה נזיח\".","ועוד הלכה בנדרים: \u0003האומר לחברו \"מודרני\u0004 (מודר אני) \u0003ממך\",\u0004 או \u0003\"מופרשני ממך\",\u0004 או \u0003\"מרוחקני ממך\"\u0004 או אמר \u0003\"שאני אוכל לך\"\u0004 או \u0003\"שאני טועם לך\",\u0004 אף על פי שלא פירש שהדבר נאסר עליו בנדר, ולא אמר כלל מה טיבו של הנדר, מכל מקום \u0003אסור.\u0004 שאנו רואים זאת כמשפט בלתי מושלם מבחינה לשונית, אבל הנדר והאיסור מובן מתוכו (והוא הקרוי \"ידות נדרים\").","אבל אם אמר \u0003\"מנודה אני לך\",\u0004 כלומר שלכאורה לא אמר במשפט זה שהוא עצמו אוסר דבר אלא שהוא מרוחק ומנודה מחבירו, \u0003ר' עקיבא היה חוכך\u0004 (מפקפק) \u0003בזה להחמיר\u0004 ולהחשיב גם דבר זה כביטוי שיש בו משמעות של החלת איסור נדר על היחסים הללו."],["שנינו במשנה \u0003\"כל כינויי נדרים כנדרים,\u0004 חרמים כחרמים, שבועות כשבועות \u0003\".\u0004 ושואלים: \u0003מאי שנא גבי\u0004 \u0005[מה שונה אצל]\u0006 המשנה הראשונה במסכת \u0003נזיר\u0004 ש\u0003לא קתני להו לכולהו\u0004 \u0005[שנה את כולם],\u0006 גם נדר ושבועה וכו', ושנה רק את השייך לענין המסכת — \"כל כינויי נזירות כנזירות\", \u0003ומאי שנא גבי\u0004 \u0005[ומה שונה אצל]\u0006 \u0003נדרים,\u0004 במשנתנו, \u0003דקתני לכולהו\u0004 \u0005[ששנה את כולם]\u0006 גם חרם, שבועה ונזירות?","ומשיבים: דווקא במשנתנו העוסקת בענייני נדר כל אלה, \u0003משום\u0004 ש\u0003נדר ושבועה כתיבי גבי הדדי\u0004 \u0005[כתובים\u0006 בתורה \u0005זה ליד זה]\u0006 (\"כי ידור נדר לה' או השבע שבועה\". במדבר ל, ג) ולכן \u0003תני תרתין\u0004 \u0005[שנה\u0006 התנא במשנתנו \u0005שתים],\u0006 גם כינויי נדרים וגם כינויי שבועות, \u0003וכיון דתני תרתין\u0004 \u0005[ששנה שתים],\u0006 \u0003תני לכולהו\u0004 \u0005[שנה את כולם].\u0006","ושואלים: אם מפני טעם זה שנה כאן גם את הדינים האחרים — \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003כינויי שבועות בתר\u0004 \u0005[\u0006מיד \u0005אחר]\u0006 כינויי \u0003נדרים!\u0004 ומשיבים: \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 \u0003נדרים\u0004 שעניינו של נדר הוא \u0003דמיתסר חפצא עליה\u0004 \u0005[שנאסר החפץ עליו,\u0006 על הנודר\u0005],\u0006 \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003חרמים,\u0004 שעיקר דינם כנדרים \u0003דמיתסר חפצא עליה\u0004 \u0005[ש\u0006אף בהם \u0005נאסר החפץ עליו,\u0006 על המחרים\u0005].\u0006 \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 להבדיל\u0005]\u0006 מדין \u0003שבועה, דקאסר נפשיה מן חפצא\u0004 \u0005[שהוא אוסר את עצמו מן החפץ],\u0006 שבשבועה אין הנשבע מטיל איסור על דבר מסויים, אלא אוסר את עצמו בעשייה מסויימת. וכיון שמצד הענין חרמים קרובים יותר לנדרים שנה אותם התנא סמוך לנדרים ואת שבועות אחריהם.","שואלים ביחס לסגנון הדברים במשנה: \u0003פתח\u0004 במשנה \u0003בכינויין \"כל כנויי נדרים\", ו\u0004מה ש\u0003מפרש\u0004 מיד אחר כך אינו כינויי נדרים אלא \u0003ידות\u0004 של נדרים, כלומר ביטויים לא מושלמים של לשונות נדר, כגון: \u0003האומר לחבירו \"מודר אני ממך\",\u0004 שאין אלה כינויי נדרים אלא ידות נדרים! \u0003ותו\u0004 \u0005[ועוד]\u0006 יש להוסיף ולתמוה: וכי \u0003ידות אינשי\u0004 \u0005[שכח]\u0006 התנא להזכיר?! שלא אמר כלל: \"ידות נדרים כנדרים\".","ומשיבים: \u0003איירי בהון\u0004 \u0005[עוסק\u0006 הוא \u0005בהם]\u0006 בידות, \u0003וחסורי מיחסרא\u0004 \u0005[וחסרה\u0006 המשנה\u0005],\u0006 \u0003והכי קתני\u0004 \u0005[וכך שנה]:\u0006 \u0003כל כינויי נדרים כנדרים וידות נדרים כנדרים,\u0004 ולכן ממשיך ומפרש מה הן ידות הנדרים.","ושואלים: \u0003וליפרוש\u0004 \u0005[ושיפרש]\u0006 את ה\u0003כינויין ברישא\u0004 \u0005[בתחילה],\u0006 כיון שהתחיל בכינויי נדרים!","ומסבירים: הדבר \u0003ההוא דסליק מיניה\u0004 \u0005[שמסיים בו],\u0006 את הדבר \u0003ההוא מפרש ברישא\u0004 \u0005[בראשונה].\u0006 וכן הוא סגנון המשנה בכלל, \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה אחרת\u0005]:\u0006 \u0003במה,\u0004 באלו פתילות ושמנים, \u0003מדליקין\u0004 נרות של שבת \u0003ובמה אין מדליקין?\u0004 וממשיכה המשנה ומפרטת: \u0003אין מדליקין כו'.\u0004 הרי שאין התנא מתחיל בפירוט הכלל הראשון \"במה מדליקין\", אלא בפירוט הכלל האחרון \"במה אין מדליקין\".","וכן שנינו במשנה נוספת כיוצא בזה: \u0003במה טומנין\u0004 את התבשיל על מנת שישאר חם בשבת \u0003ובמה אין טומנין?\u0004 ומפרטת המשנה אחר כך תחילה במה \u0003אין טומנין כו'.\u0004 וכן: \u0003במה,\u0004 באלו תכשיטים \u0003אשה יוצאה\u0004 לרשות הרבים בשבת \u0003ובמה אינה יוצאה,\u0004 מפני שעלולה להסירם ולטלטלם בידה. ומפרטים תחילה: \u0003\"לא תצא אשה\".\u0004","על הסבר זה מקשים: \u0003ו\u0004כי ב\u0003כל היכא\u0004 \u0005[מקום]\u0006 במשנה את ההלכה בה \u0003פתח לא מפרש ברישא\u0004 \u0005[בראשונה]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003יש\u0004 קרובי משפחה שהם \u0003נוחלין\u0004 (יורשים) את האדם לאחר מותו, \u0003ומנחילין\u0004 (מורישים) לו, כמו אב לבנו. ויש \u0003נוחלין ולא מנחילין,\u0004 כמו הבן את אמו. \u0003ואלו נוחלין ומנחילין\u0004 וכו', הרי שמפרש את הכלל הראשון ששנה.","וכן שנינו: \u0003יש\u0004 נשים שהן \u0003מותרות לבעליהן ואסורות ליבמיהן\u0004 (גיסיהם, אחי הבעל) אם ימות הבעל בלא בנים, מפני שהיבם אסור באשה כזו, כגון שהיבם כהן גדול והריהו אסור באלמנה. יש \u0003מותרות ליבמיהן ואסורות לבעליהן\u0004 שעברו על דברי תורה כשנישאו, ומפרט מיד \u0003ואלו מותרות לבעליהן ואסורות ליבמיהן\u0004 וכו'.","וכן שנינו בענין מנחות: \u0003יש\u0004 מנחות ה\u0003טעונות\u0004 הבאת \u0003שמן ולבונה\u0004 עליהן, ויש שיש בהן חובת \u0003שמן ולא לבונה,\u0004 ומפרט מיד: \u0003ואלו טעונות שמן ולבונה.\u0004 וכן שנינו: \u0003יש\u0004 מנחות \u0003טעונות הגשה\u0004 ומגע בקרן המזבח \u0003ואין טעונות תנופה\u0004 למעלה על ידי הכהן, ויש טעונות \u0003תנופה ולא הגשה,\u0004 וחוזר ומפרט מיד: \u0003ואלו טעונות הגשה\u0004 וכו'.","וכן שנינו: \u0003יש\u0004 אדם שהוא נחשב כ\u0003בכור ל\u0004ענין \u0003נחלה\u0004 ומקבל פי שניים בירושה מפני שהוא בכור לאביו, \u0003ואין\u0004 הוא נחשב כ\u0003בכור לכהן\u0004 לענין חובת פדיון הבן, מפני שאינו בכור לאמו, ויש שהוא \u0003בכור לכהן\u0004 וחייב בפדיון \u0003ואין\u0004 הוא \u0003בכור לנחלה,\u0004 ומפרט מיד: \u0003ואיזהו בכור לנחלה ואין בכור לכהן\u0004 וכו'. הרי שיש מקרים בהם מפרש התנא את הכלל הראשון ששנה!","ומסבירים את טעם ההבדל בין הסדרים השונים במשניות הללו: \u0003הלין\u0004 \u0005[אלו],\u0006 \u0003משום דאוושו ליה\u0004 \u0005[שרבו בהם]\u0006 הכללים \u0003מפרש\u0004 את הכלל \u0003ההוא\u0004 שבו \u0003פתח ברישא\u0004 \u0005[בתחילה],\u0006 אבל כאשר יש רק שני כללים, הריהו מתחיל לפרש מן האחרון.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 הלכה זו של \u0003במה בהמה יוצאה\u0004 מרשות היחיד לרשות הרבים בשבת \u0003ובמה אינה יוצאה דלא אוושא\u0004 \u0005[שאין\u0006 המשנה \u0005מרובה]\u0006 בכללים, שיש בה רק שניים, \u0003וקתני\u0004 \u0005[ושנה]\u0006 ופירט בתחילה את הכלל הראשון: \u0003יוצא גמל!\u0004"],["\u0003אלא לאו דווקא,\u0004 אין התנא מדקדק בדבר זה, שאין סדר אחד לכך, ו\u0003זימנין\u0004 \u0005[פעמים]\u0006 ש\u0003מפרש\u0004 את הכלל \u0003ההוא\u0004 בו \u0003פתח ברישא\u0004 \u0005[בתחילה],\u0006 \u0003זימנין\u0004 \u0005[פעמים]\u0006 את הכלל \u0003ההוא דסליק\u0004 \u0005[שסיים]\u0006 בו \u0003מפרש ברישא\u0004 \u0005[בתחילה].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר מדוע פתח התנא בפירוש ידות תחילה: \u0003ידות איידי דאתיין מדרשא\u0004 \u0005[מתוך ש\u0006הן \u0005באות,\u0006 נלמדות, \u0005מדרשה]\u0006 של הכתוב ואינן מפורשות במקרא, \u0003מפרש להון ברישא\u0004 \u0005[אותן בתחילה],\u0006 משום שחביב עליו דבר שיש בו חידוש שאינו מפורש בכתוב.","ומקשים: אם אמנם חביב עליו הדבר \u0003וליפתח הדין ברישא\u0004 \u0005[שיפתח בזה,\u0006 בידות, \u0005בתחילה,\u0006 בראשית המשנה\u0005]!\u0006 ומשיבים: \u0003מיפתח\u0004 \u0005[לפתוח]\u0006 הוא \u0003פתח בכינויין\u0004 שהם \u0003דאורייתא ברישא\u0004 \u0005[מן התורה בתחילה],\u0006 \u0003והדר מפרש\u0004 \u0005[וחזר ופירש]\u0006 \u0003ידות דאתיין ליה מדרשא\u0004 \u0005[שבאות לו מן הדרשה].\u0006","ושואלים על הסבר זה: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0005כי\u0006 ה\u0003כינויין\u0004 שהוזכרו במשנה לנדרים ולשבועות וכיוצא בהם \u0003לשון גוים הן,\u0004 ולשיטה זו כינויי נדרים הם מן התורה, שודאי תופס הנדר בכל שפה שבה שנדר. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שכינויים אלה הם \u0003לשון שבדו\u0004 (שיצרו) \u0003להן חכמים\u0004 לבני האדם \u0003להיות נודר בו\u0004 כל הרוצה בכך, כמבואר להלן (נדרים דף י, א) שרצו למעט על ידי כך הזכרת שם שמים לבטלה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי גם אלה יש בהם חידוש כמו בידות.","ומתרצים: הלא לעיקרו של דבר \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 \u0003ידות\u0004 נדרים במשנה? \u0003ולאו חסורי קא מחסרת לה\u0004 \u0005[ו\u0006האם \u0005אין אתה מחסר אותה\u0006 את המשנה\u0005],\u0006 שאתה מפרש משנה זו כאילו היה חסר בה משהו ומוסיף בה דברים? וכיון שהכנסנו כתיקון למשנה ידות נדרים, אם כן: \u0003אקדים נמי ותני\u0004 \u0005[הקדם גם כן ושנה]\u0006 \u0003ידות\u0004 בתחילה ותקן את נוסח המשנה כך: \u0003כל ידות נדרים כנדרים וכל כינויי נדרים כנדרים, ואלו הן ידות: האומר לחבירו\u0004 מודרני ממך וכו', \u0003ואלו הן כינויין: קונם, קונח, קונס.\u0004","כיון שדנו כאן בענין ידות, שואלים: \u0003וידות\u0004 נדרים \u0003היכא כתיב\u0004 \u0005[היכן\u0006 הן \u0005כתובות],\u0006 כלומר, מה היסוד והרמז לדבר במקרא? ומסבירים, נאמר: \u0003\"איש\u0004 או אשה \u0003כי יפלא לנדר נדר נזיר להזיר לה'\"\u0004 (במדבר ו, ב) \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 הכפילות \u0003\"נזיר להזיר\"\u0004 באה \u0003לעשות כינויי נזירות\u0004 שיהיו אף הם תופסים \u0003כנזירות, ו\u0004אף \u0003ידות נזירות כנזירות.\u0004","\u0003אין לי\u0004 הלכה זו \u0003אלא בנזירות,\u0004 ואולם שאף \u0003בנדרים\u0004 יהיה כמו כן, שיהיו הידות והכינויים כמותם, \u0003מנין? תלמוד לומר \"איש\u0004 או אשה \u0003כי יפלא לנדר נדר נזיר להזיר לה'\"\u0004 (במדבר ו, ב), \u0003מקיש\u0004 (משווה) הפסוק באותו ענין \u0003נזירות לנדרים ונדרים לנזירות; מה נזירות עשה בו ידות נזירות כנזירות — אף נדרים עשה בהם ידות נדרים כנדרים.\u0004","\u0003ומה נדרים\u0004 אם אין הנודר מקיים אותם הריהו \u0003עובר ב\"בל יחל\"\u0004 (\"איש כי ידור נדר לה'... לא יחל דברו\", במדבר ל, ג), \u0003ו\u0004אם אינו משלם את נדרו בזמן הריהו עובר \u0003ב\"בל תאחר\"\u0004 (\"כי תדור נדר לה' אלהיך לא תאחר לשלמו\", דברים כג, כב) — \u0003אף נזירות עובר ב\"בל יחל\"\u0004 אם לא נהג מנהגי נזירות \u0003וב\"בל תאחר\"\u0004 אם לא החל במנהג נזירות בזמן. \u0003ו\u0004כן להיפך, יש ללמוד מן ההיקש: \u0003מה נדרים האב מיפר נדרי בתו ובעל מיפר נדרי אשתו\u0004 כפי שמפורש בפרשת נדרים (במדבר פרק ל) — \u0003אף נזירות, האב מיפר נזירות בתו ובעל מיפר נזירות אשתו.\u0004","על ההסבר הזה שואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003גבי\u0004 (אצל) \u0003נזירות דכתיב\u0004 \u0005[שנאמר\u0006 בה\u0005]\u0006 \u0003\"נזיר להזיר\"\u0004 ומן הכפילות הזו למד התנא דין כינויים וידות, \u0003נדרים\u0004 עצמם \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 בהם כפילות לשון \u0003\"לנדר נדר\"\u0004 ממנה אפשר ללמוד כמו כן, \u0003ו\u0004אם כן \u0003היקישא\u0004 \u0005[היקש]\u0006 נדרים לנזירות \u0003למה לי?\u0004 הלא יכול אני ללמוד דבר זה במישרין מכפילות זו!","ומשיבים: \u0003אי כתב\u0004 \u0005[אם היה כותב]\u0006 \u0003\"נדר לנדר\" כדכתב\u0004 \u0005[כפי שכתב]\u0006 בפרשת נזיר \u0003\"נזיר להזיר\"\u0004 היה הדבר \u0003כדקאמרת\u0004 \u0005[כפי שאתה אומר],\u0006 ואכן \u0003לא\u0004 היה \u0003צריך\u0004 לשם כך \u0003היקישא\u0004 \u0005[היקש]\u0006 ואפשר היה ללמוד את הדבר הזה מן הכתוב. \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"לנדר נדר\",\u0004 אפשר לומר כי \u0003דברה תורה כלשון בני אדם,\u0004 שבצורה לשונית זו נוקט כרגיל הכתוב, ואין בזה איפוא משום לשון הדגשה והוספה.","ושואלים: \u0003הניחא למאן דאית ליה\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שיש לו,\u0006 שמקבל\u0005]\u0006 את הכלל של \u0003דברה תורה כלשון בני אדם, אלא למאן דלית ליה\u0004 \u0005[ל\u0006דעת \u0005מי שאין לו,\u0006 שאינו סובר\u0005]\u0006 כי \u0003דברה תורה כלשון בני אדם,\u0004 ובכל מקום שיש כפילות הריהי באה ללמד, \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"לנדר נדר\"\u0004 שיש בו כפילות \u0003מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו]?\u0006 ומשיבים: \u0003דריש ליה\u0004 \u0005[דורש אותו]\u0006 כך: \"לנדור נדר\" הרי זו לשון ריבוי \u0003לעשות ידות נדרים כנדרים, ומקיש\u0004 \u0005[ומשווה]\u0006 הכתוב \u0003נזירות לנדרים\u0004 הן ללמד לענין ידות, והן לשאר דברים אחרים שלמדנו מהיקש זה. ואילו את כפל הלשון \u0003\"נזיר להזיר\" דריש ליה\u0004 \u0005[דורש אותו]\u0006 בדרך אחרת: \u0003מלמד\u0004"],["\u0003שהנזירות חל על הנזירות.\u0004 שאם היה נזיר, ובתוך נזירותו אמר שוב \"הריני נזיר\" — חלה עליו חובת נזירות אחרת לכשישלים את הנזירות ראשונה.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 כי \u0003דברה תורה כלשון בני אדם\u0004 ואין לומדים ידות נדרים מ\"לנדור נדר\", \u0003ו\u0004מהצורה הבלתי רגילה של המילים \u0003\"נזיר להזיר\" דריש\u0004 \u0005[דורש]\u0006 ולמד ממנה \u0003לעשות ידות נזירות כנזירות,\u0004 אם כן הלכה זו \u0003שהנזירות חל על הנזירות מנא ליה\u0004 \u0005[מניין לו]?\u0006 \u0003הניחא אי סבירא ליה כמאן דאמר\u0004 \u0005[זה נוח אם סבור הוא כ\u0006דעת \u0005מי שאומר]\u0006 כי \u0003אין נזירות חל על נזירות\u0004 ומשום כך אין הוא זקוק למקור להלכה זו. \u0003אלא אי סבירא ליה כמאן דאמר\u0004 \u0005[אם סבור הוא כ\u0006דעת \u0005מי שאומר]\u0006 ש\u0003נזירות חל על נזירות, מנא ליה\u0004 \u0005[מניין לו]\u0006 אם כן דין זה?","ומשיבים: אף לדעתו אפשר ללמוד מכתוב זה, שכן \u0003נימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 לשון \u0003\"\u0004נזיר \u0003ליזור\", מאי\u0004 \u0005[מה]\u0006 טעם שינה וכתב לשון \u0003\"להזיר\" — שמעת מינה תרתי\u0004 \u0005[שומע,\u0006 לומד \u0005אתה\u0006 ממנה \u0005שני\u0006 דברים\u0005],\u0006 הן ידות נזירות, והן שנזירות חלה על נזירות.","ומוסיפים: \u0003במערבא אמרי\u0004 \u0005[בארץ ישראל\u0006 היו \u0005אומרים]\u0006 באופן אחר: \u0003אית\u0004 \u0005[יש]\u0006 \u0003תנא דמפיק ליה\u0004 \u0005[שמוציא,\u0006 לומד \u0005אותו]\u0006 דין \u0003ידות\u0004 הנדרים \u0003מן\u0004 הכפילות \u0003\"לנדר נדר\",\u0004 לפי שסבור שלא דיברה תורה כלשון בני אדם, \u0003ואית\u0004 \u0005[ויש]\u0006 \u0003תנא דמפיק ליה\u0004 \u0005[שמוציא,\u0006 לומד \u0005אותו]\u0006 ממקור אחר, לפי שסבור שדיברה תורה בלשון בני אדם, ולומד דין ידות \u0003מן \"ככל היצא מפיו יעשה\"\u0004 (במדבר ל, ג). שכתוב זה בא לרבות, ולהוסיף גם נדרים שאין לשונם מפורש.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בדרשת המקראות שלמדנו: \u0003ומה נדרים עובר ב\"בל יחל\"\u0004 (במדבר ל, ג) \u0003ו\"בל תאחר\" —\u0004 אף בנזירות כן. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003\"בל יחל\"\u0004 של \u0003נדרים משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 בפשטות, \u0003כגון\u0004 ש\u0003אמר \"ככר זו אוכל\" ולא אכלה\u0004 הרי הוא \u0003עובר משום \"בל יחל דברו\"\u0004 שעבר על נדרו.","\u0003אלא \"בל יחל\"\u0004 של \u0003נזירות היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]?\u0006 הלא \u0003כיון\u0004 ש\u0003אמר \"הריני נזיר\"\u0004 הרי באותו רגע \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 \u0003נזיר.\u0004 ואם \u0003אכל\u0004 ענבים במשך הזמן הזה \u0003קם ליה\u0004 \u0005[עומד הוא]\u0006 \u0003ב\u0004איסור \u0003\"בל יאכל\",\u0004 ככתוב בנזיר: \"מחרצנים ועד זג לא יאכל\" (במדבר ו, ד). אם \u0003שתה\u0004 יין \u0003קם ליה\u0004 \u0005[עומד הוא]\u0006 \u0003ב\u0004איסור של \u0003\"בל ישתה\"\u0004 ככתוב \"יין... לא ישתה\" (במדבר ו, ג), ואם כן לאיזה צורך נאמר שעובר ב\"בל יחל\"? \u0003אמר רבא:\u0004 בא מדרש זה ללמד \u0003לעבור עליו בשנים,\u0004 שעובר גם משום \"בל יחל\" על שלא קיים נדר נזירותו, וגם משום האיסור המיוחד של אכילת ענבים או שתיית יין.","ועוד שואלים: \u0003\"בל תאחר\"\u0004 של \u0003נזירות היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]?\u0006 \u0003כיון\u0004 ש\u0003אמר \"הריני נזיר\" — הוי ליה\u0004 \u0005[הריהו]\u0006 \u0003נזיר\u0004 מיד. ואם \u0003אכל\u0004 ענבים \u0003קם ליה\u0004 \u0005[עומד הוא]\u0006 מיד \u0003ב\u0004איסור של \u0003\"בל יאכל\"\u0004 ואם כן איך יכול לאחר נדר זה של נזירות? ומשיבים: \u0003באומר\u0004 ומפרש \u0003\"לכשארצה אהא נזיר\",\u0004 ואם כן אין הוא נזיר מיד. ומקשים: \u0003ואי אמר\u0004 \u0005[ואם\u0006 הוא \u0005אומר]\u0006 ומפרש \u0003\"כשארצה\"\u0004 אם כן \u0003ליכא\u0004 \u0005[אין]\u0006 בכך איסור \u0003\"בל תאחר\",\u0004 שהרי לא קבע מועד לדבר!","\u0003אמר רבא: כגון\u0004 ש\u0003אמר \"לא איפטר מן העולם עד שאהא נזיר\", דמן ההיא שעתא הוה ליה\u0004 \u0005[ש\u0006במקרה כזה \u0005מאותה שעה הריהו]\u0006 חייב להתנהג כ\u0003נזיר,\u0004 למרות שלא פירש זמן. שכיון שאין יודעים מתי הוא יפטר מן העולם הרי מספק חייב להתנהג בנזירות מיד. \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 הדין בדומה לזה, שאיש \u0003האומר לאשתו \"הרי זו גיטיך שעה אחת קודם מיתתי\"\u0004 אם היה כהן — \u0003אסורה לאכול בתרומה מיד,\u0004 שהיא נחשבת לענין זה מיד כגרושה, ואם היא בת ישראל — אסורה בתרומה. \u0003אלמא אמרינן\u0004 \u0005[מכאן\u0006 ש\u0005אנו אומרים]\u0006 \u0003כל שעתא ושעתא דילמא מיית\u0004 \u0005[שעה ושעה שמא\u0006 הוא \u0005מת]\u0006 ומשום כך נאסרת בתרומה מיד מספק. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בנזירות, \u0003לאלתר הוי\u0004 \u0005[מיד הריהו]\u0006 \u0003נזיר. דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003דילמא השתא מיית\u0004 \u0005[שמא עכשיו\u0006 הוא \u0005מת].\u0006"],["\u0003רב אחא בר יעקב אמר:\u0004 אפשר להסביר כיצד מתקיים \"בל תאחר\" בנזירות באופן אחר, \u0003כגון\u0004 ש\u0003נדר והוא\u0004 באותה שעה \u0003בבית הקברות,\u0004 כיון שאסור לנזיר לשהות בבית הקברות, ואין הנזירות חלה אלא לכשיצא משם ויטהר מטומאת המת, הרי כל עוד הוא שוהה שם הריהו מעכב את חלות נדרו ועובר ב\"בל תאחר\".","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שהנודר נדר נזירות בבית הקברות \u0003לא חיילא עליה\u0004 \u0005[חלה עליו]\u0006 \u0003נזירות מאלתר\u0004 \u0005[מיד]\u0006 אלא לכשיצא מבית הקברות. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003מאלתר חיילא עליה\u0004 \u0005[מיד חלה עליו]\u0006 נזירות, אם כן \u0003מי איכא\u0004 \u0005[האם יש]\u0006 כאן איסור \u0003\"בל תאחר\"? ועוד\u0004 אפשר להוסיף ולשאול: \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003מר בר רב אשי:\u0004 לכל הדעות, הנודר נזירות בבית הקברות \u0003חיילא\u0004 \u0005[חלה]\u0006 \u0003נזירות עליה מאלתר\u0004 \u0005[עליו מיד],\u0006 ואינו צריך לחזור ולנדור נזירות לכשיצא, \u0003וכי פליגי\u0004 \u0005[וכאשר נחלקו]\u0006 חכמים בענין זה — \u0003לענין מלקות פליגי\u0004 \u0005[\u0006הם \u0005חלוקים]\u0006 אם לוקה כאשר עובר אז על איסורי נזיר, כגון ששותה יין, אבל איסור יש לדעת כולם!","ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 אפשר לומר כי \u0003קם ליה\u0004 \u0005[עומד הוא]\u0006 \u0003ב\u0004איסור של \u0003\"בל תאחר\" משום דקא\u0004 \u0005[שהוא]\u0006 \u0003מאחר\u0004 על ידי המשך שהייתו בבית הקברות \u0003נזירות\u0004 של \u0003טהרה,\u0004 שהרי מכל מקום צריך לקיים נדר נזירות בטהרה, ונזירות זו שחלה עליו מיד אינה נזירות טהרה אלא נזירות של טמא. \u0003אמר רב אשי: הואיל וכן\u0004 כלומר, לפי נימוק זה, \u0003נזיר שטימא עצמו במזיד, עובר,\u0004 מלבד על האיסור להיטמא, גם \u0003משום \"בל תאחר\"\u0004 של \u0003נזירות\u0004 של \u0003טהרה,\u0004 שהרי על ידי כך הוא גורם שלא ישלים את נזירותו בטהרה בזמנה.","\u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר\u0004 הסבר אחר כיצד מתקיים \"בל תאחר\" של נזירות: שהרי יש עליו ציווי לגלח שער ראשו בגמר הנזירות, ואם גורם לתגלחת שתתאחר הריהו \u0003עובר ב\"בל תאחר\" תגלחתו.\u0004","ומעירים: \u0003ולא מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003תגלחת מעכבת\u0004 בנזיר, וכל עוד לא גילח עדיין כל איסורי נזיר חלים עליו, שיש בעיכוב תגלחתו משום \"בל תאחר\" \u0003אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003תגלחת אינה מעכבת\u0004 ומיד לאחר שמביא את קרבנותיו בטל ממנו דין הנזירות, \u0003מצות גילוח מיהא לא מיקיים\u0004 \u0005[מכל מקום אינה מתקיימת],\u0006 ויש בזה משום \"בל תאחר\".","\u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי אמר\u0004 הסבר אחר כיצד מתקיים \"בל תאחר\" בנזירות: \u0003עובר ב\"בל תאחר\" קרבנותיו,\u0004 שאם השלים את נזירותו ולא הביא קרבנותיו לבית המקדש הריהו עובר בכך על \"בל תאחר\".","על ההסבר האחרון שואלים: \u0003ומן הכא נפקא ליה\u0004 \u0005[ומכאן,\u0006 מן ההיקש לנדרים, \u0005יוצא לו]\u0006 הדבר? הלא \u0003מהתם נפקא ליה\u0004 \u0005[משם,\u0006 מלימוד אחר, \u0005יוצא לו]\u0006 דין זה, שנאמר: \"כי תידור נדר... לא תאחר לשלמו כי דרוש ידרשנו ה' אלקיך מעמך\" (דברים כג, כב), ואת המילים \u0003\"כי דרש ידרשנו\"\u0004 דרשו: \u0003אלו חטאת ואשמות\u0004 שעובר עליהם ב\"בל תאחר\", ובכלל זה חטאת ואשם של נזיר!","ומסבירים: בכל זאת יש צורך בלימוד זה של היקש לנדרים, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003חידוש הוא שחידשה תורה בנזיר\u0004 בענין זה, ואין ללמוד דין חטאת נזיר משאר חטאות.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הוא \u0003חידוש\u0004 זה שחידשה תורה בנזיר? \u0003אילימא\u0004 \u0005[אם תרצה לומר]\u0006 \u0003דלא מתפיס ליה\u0004 \u0005[שאינו\u0006 יכול \u0005להתפיס אותו]\u0006 את \u0003חטאת נזיר בנדר.\u0004 שאם סתם אדם, שאינו נזיר, אומר \"הרי עלי חטאת נזיר\" אין נדרו חל כלל, והרי זה חידוש להקל בחטאת הנזיר, ומשום כך יש צורך בהיקש לנדרים לענין \"בל תאחר\". אולם אין זה דין מיוחד בחטאת נזיר ש\u0003הרי חטאת חלב,\u0004 כלומר, חטאת רגילה שמביא אדם כשעשה בשגגה איסור חמור, כגון אכילת חלב, \u0003שאין מתפיסה בנדר\u0004 שגם היא אינה נתפסת לקדושה בנדר, שאין כל אדם יכול להקדישה אלא אם כן עבר עבירה זו, \u0003ו\u0004בכל זאת \u0003עובר ב\"בל תאחר\"\u0004 אם לא הביא אותה!","\u0003אלא\u0004 יש לומר באופן אחר: \u0003מאי חידושיה\u0004 \u0005[מה חידושו]\u0006 של נזיר — \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואם אמר \"הריני נזיר\" אפילו מן חרצן\u0004 ענבים בלבד, שפירש שנזירות זו היא רק על פרט אחד מאיסורי נזיר, כגון על אכילת חרצן, למרות שפירש זאת — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003נזיר לכל,\u0004 שכל דיני נזירות חלים עליו, וכיון שדין זה חידוש הוא \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא ליעבור עליה\u0004 \u0005[יעבור עליו]\u0006 על נדר כגון זה \u0003משום \"בל תאחר\" — על כן קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ההיקש לנדרים שאף בזה יש דין \"לא תאחר\".","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003כי נזיר\u0004 \u0005[כאשר נוזר]\u0006 \u0003מן חרצן הוי\u0004 \u0005[הריהו]\u0006 \u0003נזיר לכל,\u0004 לכל פרטי האיסורים בנזיר, \u0003אלא ל\u0004דעת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 ש\u0003אין\u0004 הוא \u0003נזיר עד שיזיר\u0004 בפירוש \u0003מכולן,\u0004 מכל הדברים האסורים בנזיר — \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003ועוד\u0004 אפשר להקשות: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003חידוש\u0004 הלא \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 \u0003הוא,\u0004 שנזיר חמור בזה יותר משאר נדרים, שהרי חלים עליו כל הפרטים הנובעים מן הנדר, גם אם התכוון שלא יחול אלא במקצת. ואיך ניתן להסיק מכך להקל עליו ולומר שלא יעבור עליו ב\"בל תאחר\" כעל שאר נדרים, ולהצריך היקש מיוחד לצורך זה!","\u0003אלא\u0004 יש להסביר בדרך אחרת: \u0003מאי חידושיה\u0004 \u0005[מה חידושו]\u0006 של נזיר; \u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]:\u0006 \u0003הואיל\u0004"],["\u0003ואם גילח על אחת משלשתן,\u0004 שצריך הנזיר כשמשלים נזירותו להביא שלשה קרבנות, עולה חטאת ושלמים, ואם גילח לאחר שהביא רק אחד מהם — \u0003יצא\u0004 ידי חובתו, וזהו חידוש להקל, ומשום כך היינו אומרים ש\u0003לא ליעבור עליה\u0004 \u0005[יעבור עליו]\u0006 \u0003ב\"בל תאחר\",\u0004 שהרי עיקר נזרו יוצא בו בקרבן אחד בלבד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שעל כל קרבן וקרבן יש גם ציווי של \"בל תאחר\".","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כפי שכבר אמרנו קודם: \u0003מאי חדושיה\u0004 \u0005[מה חידושו]\u0006 של הנזיר — \u0003משום\u0004 שקרבנות נזיר \u0003לא מתפיסו\u0004 \u0005[נתפסים]\u0006 \u0003בנדר,\u0004 שאינו יכול להקדיש אותם אלא אם כן היה נזיר כפי שאמרנו. \u0003והא דקא קשיא\u0004 \u0005[וזה שהיה קשה]\u0006 \u0003לך\u0004 מענין \u0003חטאת חלב\u0004 שגם אותה אי אפשר לנדור אלא אם כן מתחייב בה, ובכל זאת עובר עליה ב\"בל תאחר\" — זו אינה קושיה, כי יש הבדל בין הדברים, שהרי \u0003חטאת חלב קאתיא\u0004 \u0005[באה]\u0006 \u0003לכפרה,\u0004 ומשום כך עובר ב\"בל תאחר\" כשמאחר להביא כפרתו. אבל \u0003חטאת נזיר למאי אתיא\u0004 \u0005[למה\u0006 היא \u0005באה]?\u0006 שהרי אינה באה לכפר על עוון, ומכל מקום אינה נתפסת בנדר, ומשום כך יש מקום לומר שלא יעבור עליה ב\"בל תאחר\".","ומקשים: \u0003והרי חטאת יולדת\u0004 שגם היא \u0003לא אתיא\u0004 \u0005[באה]\u0006 \u0003לכפרה, ו\u0004בכל זאת \u0003עבר עלה\u0004 \u0005[עובר עליה]\u0006 \u0003משום \"בל תאחר\"!\u0004 ומשיבים: \u0003ההיא,\u0004 חטאת יולדת, שונה היא, משום שיש לה מטרה מסויימת — ד\u0003קא שריא\u0004 \u0005[שהיא מתירה]\u0006 \u0003לה,\u0004 ליולדת, \u0003למיכל\u0004 \u0005[לאכול]\u0006 \u0003בקדשים,\u0004 ולכן, אף שאינה באה לכפרת עוון, מכל מקום היא באה להתיר. אבל חטאת נזיר אין לה תפקיד מסויים ומיוחד, ולכן חידוש הוא שאינה באה בנדר, ומשום כך צריכים אנו לימוד מיוחד לחייב נזיר ב\"בל תאחר\".","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003ומה נדרים האב מיפר נדרי בתו ובעל מיפר נדרי אשתו — אף נזירות האב מיפר נזירות בתו ובעל מיפר נזירות אשתו.\u0004 ושואלים: \u0003למה לי היקשא\u0004 \u0005[ההיקש]\u0006 שבכתוב כדי ללמדנו הלכה זו? \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003ב\u0004דרך הלימוד של \u0003\"מה מצינו\u0004 (מצאנו) \u0003\"\u0004מן הדין של \u0003נדרים;\u0004 מה מצאנו בנדרים שהבעל והאב מפירים — אף בנדרים של נזירות כן, ואין צורך לכך להיקש מיוחד בכתוב!","ודוחים: אילו לא למדנו מההיקש לא היינו לומדים כן מנדרים, כי \u0003דילמא\u0004 \u0005[שמא]\u0006 היינו אומרים כך: רק \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003נדרים הוא\u0004 ש\u0003מיפר, משום דלא אית ליה קיצותא\u0004 \u0005[שאין לו קיצבה],\u0006 שהרי נדר יכול להיות לזמן בלתי מוגבל, ומשום כך יכול האב או הבעל להפר, \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003נזירות דאית ליה קיצותא\u0004 \u0005[שיש לו\u0006 לנדר \u0005קיצבה]\u0006 שהרי \u0003סתם נזירות שלשים יום, אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יוכל להפר, שהרי יש לנדר תקנה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת יכול להפר. ודין זה היה צריך להיקש מיוחד, ולא יכולנו ללמדו בדרך \"מה מצינו\".","שנינו במשנה ש\u0003האומר לחבירו מודר אני,\u0004 וכן שאר לשונות שאינן אלא ידות נדרים, ר' עקיבא היה חוכך בהן להחמיר ולהחשיבם כנדר. \u0003אמר שמואל: בכולן,\u0004 בכל אותן ידות נדרים שאמרנו שנאסר מחמת הנדר: \"מודרני ממך\" \"מופרשני ממך\" \"מרוחקני ממך\", אין די שיאמר בנוסח \"מודר אני\" כדי לאוסרו בנדר, שאין בו כל הגדרה של מהות הנדר, אלא \u0003עד שיאמר\u0004 בנוסח מוגדר, כגון \"מודר אני \u0003שאני אוכל לך\",\u0004 או \"מודר אני \u0003שאני טועם לך\".\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: אם אמר \u0003\"מודר אני ממך\" \"מופרשני ממך\" \"מרוחקני ממך\" — הרי זה אסור. \"שאני אוכל לך\" \"שאני טועם לך\" — הרי זה אסור!\u0004 משמע שאלה הם שני עניינים נבדלים, ודי באחד מהם כדי לאוסרו, ואין צריך לומר את שניהם יחד. ומשיבים: \u0003הכי קתני\u0004 \u0005[כך שנה],\u0006 כלומר, כך צריך להבין: אין כאן שתי סדרות של דינים שונים, אלא הקטע השני כוונתו: \u0003במה דברים אמורים\u0004 שהאומר \"מודר אני ממך\" אסור — \u0003באומר\u0004 ומוסיף \u0003\"שאני אוכל לך\" \"שאני טועם לך\".\u0004","ומקשים: \u0003והתניא איפכא\u0004 \u0005[והרי שנויה\u0006 ברייתא בסדר \u0005הפוך]:\u0006 \u0003\"שאני אוכל לך\" \"שאני טועם לך\" — אסור, \"מודרני ממך\" ו\"מופרשני ממך\" \"מרוחקני ממך\" — הרי זה אסור!\u0004 וסדר זה ש\"מודרני\" בא לאחר \"שאני אוכל לך\" וודאי שלא ניתן לפרש בדרך של \"במה דברים אמורים\"! ומשיבים: \u0003תני הכי\u0004 \u0005[שנה כך]:\u0006 כשהוא אומר \"שאני טועם לך\" \"שאני אוכל לך\" מתי הוא אסור — דווקא כאשר \u0003וכבר אמר \"מודרני\".\u0004","ומקשים: \u0003אי הכי היינו רישא\u0004 \u0005[אם כך זהו ראשה]\u0006 של הברייתא, כלומר, הרי זו כעין הברייתא הראשונה, בלא חידוש! \u0003ועוד:\u0004 אם היה כל זה ענין אחד — לשון \u0003\"אסור\" \"אסור\"\u0004 הכתובה פעמיים בהלכה זו \u0003למה ליה למתני\u0004 \u0005[לו\u0006 \u0005לשנות]?\u0006 שהרי לפירוש זה יש כאן רק ענין אחד!","\u0003אלא\u0004 יש לחזור בנו ממה שאמרנו, ולומר את הדברים באופן אחר, \u0003אמר שמואל: טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר\u0004 והוסיף למילים \"מודרני ממך\" הפירוט \u0003\"שאני אוכל לך\" \"שאני טועם לך\" הוא אסור\u0004 בשל חבירו \u0003וחבירו מותר\u0004 בשלו, שלשון זו מוכיחה שהוא מחיל את הנדר רק על עצמו."],["\u0003אבל\u0004 אם \u0003אמר \"מודרני הימך\" לחודיה\u0004 \u0005[לבדו]\u0006 — \u0003שניהן אסורין,\u0004 שלשון זו אינה מבחינה אם הוא רוצה להדיר את עצמו מליהנות מחבירו, או רוצה להדיר את חבירו שייאסר ליהנות ממנו. \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר ר' יוסי בר' חנינא:\u0004 האומר \u0003\"מודרני הימך\" — שניהן אסורין.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 האומר לחבירו \u0003\"הריני עליך חרם\" — המודר,\u0004 האיש האחר שאליו נאמר הדבר, \u0003אסור\u0004 ליהנות מן המדיר, שהרי האומר עשה את עצמו חרם עבור אותו אדם, \u0003אבל מדיר לא,\u0004 אינו אסור ליהנות מן המודר. ומדוע לא נאמר גם כאן כדברי שמואל ששניהם אסורים? ומשיבים: כאן מדובר \u0003כגון דפריש\u0004 \u0005[שפירש]\u0006 ואמר: \u0003\"ואת\u0004 \u0005[ואתה]\u0006 \u0003עלי לא\u0004 תהיה חרם\u0003\".\u0004","ומקשים, שנינו שם עוד: אם אומר \u0003\"את עלי חרם\" — הנודר אסור, אבל מודר לא.\u0004 ובניגוד לדברי שמואל! ומשיבים: אף כאן \u0003כגון דפריש\u0004 \u0005[שפירש]\u0006 \u0003\"ואנא עלך\u0004 \u0005[ואני עליך]\u0006 \u0003לא\".\u0004","ושואלים: \u0003אבל\u0004 אם אמר \u0003סתמא\u0004 \u0005[סתם]\u0006 לשון זו \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? לפי זה מובן ש\u0003שניהן אסורים.\u0004 אולם \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנה בסוף]:\u0006 אם אמר \u0003\"הריני עליך ואת עלי\" — שניהן אסורים,\u0004 נדייק שדווקא \u0003הדין\u0004 \u0005[זה]\u0006 \u0003הוא\u0004 האופן ש\u0003שניהם אסורין, הא סתמא\u0004 \u0005[הרי\u0006 כשאמר \u0005סתם]\u0006 כגון \"את עלי חרם\", ולא פירש \"והריני עליך\" — \u0003הוא אסור וחברו מותר!\u0004","\u0003אלא הכי אתמר\u0004 \u0005[כך נאמר]\u0006 בדברי \u0003ר' יוסי בר' חנינא: \"מודר אני לך\" — שניהם אסורין,\u0004 שמלשון זו משמע שעל שניהם חל הנדר, אבל אם אמר \u0003\"מודרני הימך\" — הוא אסור וחברו מותר.\u0004","ומקשים: \u0003והא מתניתין דקתני\u0004 \u0005[והרי משנתנו ששנה]\u0006 בה במפורש \u0003\"הימך\", ואוקימנא למתניתין\u0004 \u0005[והעמדנו את משנתנו]\u0006 \u0003ל\u0004דעת \u0003שמואל: בכולן עד שיאמר \"שאני טועם לך\" ו\"שאני אוכל לך\" הוא\u0004 ש\u0003אסור וחברו מותר, אבל ב\u0004אומר \u0003\"מודרני הימך\", שניהם אסורין.\u0004 וקשה לשמואל!","\u0003אלא\u0004 יש לדחות מה שאמרנו ולומר כך: \u0003מעיקרא\u0004 \u0005[מעיקרם]\u0006 של דברי \u0003שמואל הכי איתמר\u0004 \u0005[כך נאמר]:\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא ש\u0003אמר \"שאני אוכל לך\" ו\"שאני טועם לך\" הוא\u0004 ש\u0003אין הוא אסור אלא באכילה. הא\u0004 \u0005[אבל]\u0006 אם אמר בלשון כללית יותר \u0003\"מודרני ממך\" — אסור אפילו בהנאה.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היתה כוונתו, \u0003לימא\u0004 \u0005[יאמר]\u0006 \u0003שמואל הכי\u0004 \u0005[כך]:\u0006 \u0003ואם לא אמר אלא \"שאני אוכל לך\" ו\"שאני טועם לך\" אין אסור אלא באכילה.\u0004 שהרי לשונו \"עד שיאמר\", מורה ש\"שאני אוכל לך\" מוסיף איסור על הנאמר ב\"מודרני\"!","\u0003אלא,\u0004 יש לדחות את מה שאמרנו ו\u0003הכי איתמר\u0004 \u0005[כך נאמר]\u0006 בדברי שמואל: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא ש\u0003אמר: \"שאני אוכל לך\" ו\"שאני טועם לך\" הוא\u0004 ש\u0003אסור, אבל\u0004 אם \u0003אמר\u0004 לשון: \u0003\"מודרני הימך\" לא משמע\u0004 מדברים אלה ש\u0003אמר\u0004 שהוא \u0003אסור\u0004 בנדר כלל. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שאפשר לומר כי מה שאמר \u0003\"מודר אני ממך\" — לא משתעינא בהדך\u0004 \u0005[אין אני מדבר איתך]\u0006 \u0003משמע,\u0004 וכן אם אמר \u0003\"מופרשני ממך\" — דלא עבידנא\u0004 \u0005[שאין אני עושה]\u0006 \u0003עמך משא ומתן משמע\u0004 הדבר. וכן אם אמר \u0003\"מרוחקני ממך\" — דלא קאימנא\u0004 \u0005[שאין אני עומד]\u0006 \u0003בארבע אמות דילך\u0004 \u0005[שלך]\u0006 \u0003משמע.\u0004 אבל כל אלה אינם נדר ממש שאוסר עצמו מהנאה ואכילה אצל חבירו זה, כי הלשונות הללו אינן ברורות דיין."],["ושואלים: אם כן, \u0003לימא קסבר\u0004 \u0005[האם\u0006 לומר מכאן ש\u0005סבור]\u0006 \u0003שמואל\u0004 כי \u0003ידים שאין מוכיחות לא הוויין\u0004 \u0005[אינן\u0006 נחשבות\u0005]\u0006 \u0003ידים?\u0004 כלומר, שאם ה\"יד\", הביטוי הבלתי־שלם שהשתמש בו, אינו מוכיח מעצמו את כוונת הדברים — אין הוא נחשב ל\"יד\"? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 ואכן, \u0003שמואל מוקים לה למתניתין\u0004 \u0005[מעמיד אותה את משנתנו]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה,\u0004 ש\u0003אמר: ידים שאין מוכיחות לא הוויין\u0004 \u0005[אינן\u0006 נחשבות\u0005]\u0006 \u0003ידים.\u0004","ומה ההוכחה שזו שיטתו של ר' יהודה — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003גופו\u0004 (עיקרו) \u0003של גט\u0004 שנותן אדם לאשתו כאשר מגרשה הוא המשפט הכתוב בו: \u0003\"הרי את מותרת לכל אדם\". ר' יהודה אומר:\u0004 יש עוד קטע אחד שהוא חלק מהותי בגט, שכותב \u0003\"ודין דיהוי ליכי מינאי\u0004 \u0005[וזה שיהא לך ממני]\u0006 \u0003ספר תירוכין\u0004 \u0005[גירושין]\u0006 \u0003ואיגרת שבוקין\u0004 \u0005[שילוחים]\u0006 וגט פטורין\u0003\".\u0004 ומכאן משמע שאף על פי שמובן ממה שכותב לה בשטר ונותן לה שזהו הגט, מצריך ר' יהודה שיכתוב במפורש שהוא מגרשה בגט זה, ולא בדיבור בלבד.","ושואלים: \u0003אמאי דחיק\u0004 \u0005[מדוע דוחק]\u0006 \u0003שמואל לאוקומה למתניתין\u0004 \u0005[להעמיד את משנתנו]\u0006 דווקא \u0003כ\u0004דעת \u0003ר' יהודה\u0004 שהיא דעת יחיד? \u0003לוקמה כרבנן\u0004 \u0005[\u0006ש\u0005יעמיד\u0006 ויפרש \u0005אותה כ\u0006דעת \u0005חכמים]\u0006 שאף אם אמר \"מודרני\" או \"מרוחקני\" בלבד אסור באכילה \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אין\u0004 ביטויים אלה \u0003ידים מוכיחות?\u0004","\u0003אמר רבא: מתניתין קשיתיה\u0004 \u0005[משנתנו\u0006 היתה \u0005קשה לו];\u0006 \u0003אמאי תאני\u0004 \u0005[מדוע שנה]\u0006 \u0003\"שאני אוכל לך\" \"שאני טועם לך\"? ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"שאני אוכל\" \"שאני טועם\",\u0004 ומדוע צריך להוסיף גם \"לך\", שהרי ברור שהוא מדבר לאדם מסויים ואליו הוא מפנה את הדברים הללו! אלא \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003ידים מוכיחות,\u0004 ואם אמר סתם \"שאני אוכל\", אף שמתוך ההקשר נראה שהוא נודר ואוסר על עצמו מלאכול אצל האיש שהוא מדבר אליו, אולם כיון שדבר זה אינו מתפרש מדבריו — אין זו נחשבת כאמירה מחייבת.","אותה בעיה שהזכרנו קודם בדרך אגב דנים בה עכשיו במלואה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה של \u0003ידים שאין מוכיחות. אביי אמר: הוויין\u0004 \u0005[הריהן\u0006 נחשבות\u0005]\u0006 \u0003ידים, ורבא אמר: לא הוויין\u0004 \u0005[אין הן]\u0006 \u0003ידים. אמר רבא: ר' אידי אסברא\u0004 \u0005[הסביר]\u0006 \u0003לי\u0004 את המקור לענין הזה: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"נזיר להזיר לה'\"\u0004 (במדבר ו, ב), \u0003מקיש\u0004 \u0005[משווה]\u0006 פסוק זה \u0003ידות נזירות לנזירות,\u0004 ומתוך היקש זה נלמד: \u0003מה\u0004 קבלת \u0003נזירות\u0004 צריכה להיות \u0003בהפלאה,\u0004 כלומר, בהגדרה לשונית ברורה ומוכחת — \u0003אף ידות נזירות\u0004 צריכות להיות \u0003בהפלאה,\u0004 בלשון ברורה, שמובנה מוכח מתוכה.","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' יהודה ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003קמיפלגי\u0004 \u0005[חלוקים]\u0006 אביי ורבא? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003גופו של גט — \"הרי את מותרת לכל אדם\", ר' יהודה אומר\u0004 שצריך להוסיף: \u0003\"ודין דיהוי ליכי מינאי\u0004 \u0005[וזה יהיה לך ממני]\u0006 \u0003ספר תירוכין\u0004 \u0005[גירושין]\u0006 \u0003וגט פטורין ואיגרת שבוקין\u0004 \u0005[שילוחין]\u0006 \u0003\".\u0004 האם נאמר כי \u0003אביי,\u0004 ש\u0003אמר\u0004 שידיים שאין מוכיחות נחשבות לידיים, סבור \u0003כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים],\u0006 \u0003ורבא\u0004 ש\u0003אמר\u0004 שידיים שאינן מוכיחות אינן נחשבות כידיים סבור \u0003כ\u0004שיטת \u0003ר' יהודה?\u0004","ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך אביי: אנא דאמרי\u0004 \u0005[אני\u0006 מה \u0005שאמרתי]\u0006 \u0003אפילו ל\u0004שיטת \u0003ר' יהודה\u0004 אני אומר כן. ומסבירים: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהודה\u0004 ש\u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003ידים מוכיחות — אלא גבי\u0004 (אצל) \u0003גט,\u0004 וזאת משום \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שתהיה בגט \u0003כריתות,\u0004 ניתוק גמור של הקשר בין בני הזוג, ולכן צריך לברר את הענין לחלוטין — \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005].\u0006 \u0003אבל בעלמא\u0004 \u0005[בכלל]\u0006 — \u0003מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 אומר שידיים שאין מוכיחות אינן ידיים?","\u0003ורבא אמר\u0004 \u0005[\u0006יכול \u0005היה לומר]:\u0006 \u0003אנא דאמרי\u0004 \u0005[אני\u0006 מה \u0005שאמרתי]\u0006 הוא \u0003אפילו לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים].\u0006 כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן דלא בעינן\u0004 \u0005[אמרו חכמים שאיננו צריכים]\u0006 שיהיו \u0003ידים מוכיחות אלא גבי\u0004 (אצל) \u0003גט,\u0004"],["שודאי \u0003אין אדם מגרש את אשת חבירו,\u0004 ולכן ברור מדבריו שהוא כותב את הגט לאשתו, \u0003אבל בעלמא\u0004 \u0005[בכלל]\u0006 — \u0003מי שמעת להו\u0004 \u0005[האם שמעת אותם]\u0006 שהם סומכים על ידיים שאין מוכיחות?","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: אם אמר על חפץ שמונח לפניו \u0003\"הרי הוא עלי\"\u0004 או אמר \u0003\"הרי זה [עלי]\" —\u0004 הרי זה \u0003אסור\u0004 משום נדר, \u0003מפני שהוא יד לקרבן.\u0004 ונדקדק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר \"עלי\" הוא\u0004 ש\u0003אסור, אבל\u0004 אם \u0003לא אמר \"עלי\"\u0004 אלא אמר רק \"הרי הוא\" — \u0003לא\u0004 יהא אסור, ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דעתו של \u0003אביי\u0004 שאומר שאף ידיים שאין מוכיחות נחשבות ידיים!","ומתרצים: \u0003אמר\u0004 \u0005[\u0006יכול \u0005היה לומר]\u0006 \u0003לך אביי: טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר \"עלי\" הוא\u0004 ש\u0003אסור, אבל\u0004 אם \u0003אמר \"הרי הוא\" ולא אמר \"עלי\" —\u0004 אין הלשון ברורה כלל, ואין זו אפילו \"יד\" שאינה מוכיחה, שאין מובן מדברים אלה מה טיבה של יד זו, כי אפשר לומר ש\u0003\"הרי הוא\u0004 של \u0003הפקר\",\u0004 או \u0003\"הרי הוא\u0004 של \u0003צדקה\" קאמר\u0004 \u0005[\u0006הוא \u0005אומר].\u0006 ולכן רק כאשר הוא אומר \"עלי\", מובן מדבריו שהוא מתכוון לאסור עליו והרי זה נחשב יד לנדר. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"מפני שהוא יד לקרבן\" קתני\u0004 \u0005[שנה]!\u0006 שמלשון זה משמע שעצם הענין שהוא מתכוון לקרבן נובעת מן הביטוי \"הרי הוא\", שכך היא לשון הקדש, ובכל זאת הוצרך להוסיף ולפרש \"עלי\"!","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר \"עלי\"\u0004 אז \u0003הוא אסור\u0004 באותו חפץ, לפי שאסרו עליו בנדר, \u0003וחבירו מותר. אבל\u0004 אם \u0003אמר \"הרי הוא\"\u0004 ולא אמר \"עלי\" — \u0003שניהן אסורין.\u0004 כלומר, הכל אסורים בו, ומדוע — \u0003דדלמא\u0004 \u0005[ששמא]\u0006 \u0003\"הרי הוא הקדש\" קאמר\u0004 \u0005[אמר]\u0006 שמא הקדיש אותו ממש, ולא רק נדר ממנו לאוסרו עליו כעין הקדש. ואם לכך התכוון, הרי זה אסור על הכל.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: האומר \u0003\"הרי זו חטאת\" \"הרי זו אשם\", אף על פי שהוא חייב חטאת ואשם — לא אמר כלום\u0004 ואין הבהמה מוקדשת על ידי אמירה זו, שאי אפשר להקדיש קרבן חטאת ואשם כנדבה. אבל אם אמר \u0003\"הרי זו חטאתי\" \"הרי זו אשמי\", אם היה מחויב\u0004 בקרבן זה — \u0003דבריו קיימין.\u0004 ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003אביי,\u0004 שהרי עולה מכאן שידיים שאינן מוכיחות אינן נחשבות לידיים, שהרי כשאמר רק \"הרי זו חטאת\" הרי זו יד שאינה מוכיחה שכוונתו לחטאת שלו!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך אביי: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — שיטת \u0003ר' יהודה היא,\u0004 שאמר שידיים שאינן מוכיחות אינן ידיים. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי הוא\u0004 ש\u0003אמר: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 שידיים שאינן מוכיחות הריהן ידיים — \u0003אפילו ל\u0004דברי \u0003ר' יהודה\u0004 אמרתי! ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 מדבריו, ומסכים שאין שיטתו כדברי ר' יהודה.","ושואלים: \u0003אלא לימא\u0004 \u0005[נאמר]\u0006 לפי מה שאמרנו שחזר בו אביי וסבור שמחלוקתו עם רבא היא בעצם מחלוקת תנאים, אם כן גם \u0003רבא\u0004 ש\u0003אמר\u0004 ידיים שאינן מוכיחות אינן ידיים, חזר בו ו\u0003כר' יהודה\u0004 אמר את דבריו ולא כחכמים?","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי — \u0003אפילו לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 אמרתי. כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן\u0004 \u0005[אמרו חכמים]\u0006 \u0003דלא בעינן\u0004 \u0005[שאין אנו צריכים]\u0006 שיהיו \u0003ידים מוכיחות, אלא גבי\u0004 (אצל) \u0003גט,\u0004 וזאת לפי ש\u0003אין אדם מגרש את אשת חבירו, אבל בעלמא בעינן\u0004 \u0005[בכלל צריכים אנו]\u0006 שיהיו \u0003ידים מוכיחות.\u0004"],["\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: יש יד לקידושין, או לא?\u0004 האם גם בקידושין מתחשבים באמירה בלתי מושלמת, או שאין הקידושין חלים במקרה כזה? ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 במקרה ש\u0003אמר לה לאשה \"הרי את מקודשת לי\" ואמר לחבירתה \"ואת נמי\"\u0004 \u0005[גם כן],\u0006 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שהקידושין של השניה חלים במקרה זה, שהרי \u0003היינו\u0004 \u0005[הרי אלו]\u0006 \u0003קידושין עצמן,\u0004 ואין צורך בדיבור מפורש יותר מזה! \u0003אלא כגון\u0004 ש\u0003אמר לה לאשה \"הרי את מקודשת לי\" ואמר לה לחבירתה \"ואת\",\u0004 והשאלה היא: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003\"ואת נמי\u0004 \u0005[גם כן]\u0006 מקודשת \u0003\"\u0004\u0003אמר לה לחבירתה, ותפסי\u0004 \u0005[ותופסים]\u0006 \u0003בה קידושין לחבירתה, או דלמא\u0004 \u0005[שמא]\u0006 מה שאמר \"ואת\" — \u0003\"ואת חזאי\"\u0004 \u0005[רואה]\u0006 \u0003אמר לה לחבירתה, ו\u0004אם כן \u0003לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה קידושין בחבירתה?\u0004","ושואלים: \u0003ומי מיבעי ליה\u0004 \u0005[והאם היה\u0006 דבר זה \u0005מסופק לו]\u0006 \u0003לרב פפא? והא מדאמר ליה\u0004 \u0005[והרי מ\u0006מה \u0005שאמר לו]\u0006 \u0003רב פפא לאביי\u0004 בשאלה בדין קידושין: \u0003מי סבר\u0004 \u0005[האם סבור]\u0006 \u0003שמואל\u0004 ש\u0003ידים שאין מוכיחות\u0004 (שאין כוונתו מוכחת מתוכן) \u0003הויין\u0004 \u0005[הריהן]\u0006 \u0003ידים — מכלל\u0004 הדברים, מתוך שאלתו, אפשר להבין \u0003דסבירא ליה\u0004 \u0005[שסבור הוא]\u0006 \u0003לרב פפא\u0004 שלגבי ידיים מוכיחות אין מקום לשאלה כלל, ואם כן ברור ש\u0003יש יד לקידושין!\u0004 ומשיבים: \u0003חדא מגו מאי דסבירא ליה\u0004 \u0005[אחת מתוך מה ש\u0006היה \u0005סבור לו]\u0006 \u0003ל\u0004דעת \u0003שמואל אמר ליה\u0004 \u0005[לו]\u0006 רב פפא \u0003לאביי,\u0004 שמה ששאל את אביי אינו מוכיח לגבי דעת רב פפא עצמו, אלא היא שאלה על פי מה שהבין בשיטת שמואל, ואין כאן הבעת דעה בענין זה.","ועוד, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: יש יד לפאה, או אין יד לפאה?\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 במקרה ש\u0003אמר \"הדין אוגיא ליהוי\u0004 \u0005[ערוגה זו תהא]\u0006 \u0003פאה והדין נמי\u0004 \u0005[וזו גם כן]\u0006 \u0003\",\u0004 מה מקום לשאלה? \u0003ההיא פיאה מעלייתא\u0004 \u0005[מעולה,\u0006 גמורה\u0005]\u0006 \u0003היא,\u0004 שאמירה זו היא מפורשת. ומסבירים: \u0003כי קא מיבעיא ליה\u0004 \u0005[כאשר נשאלה לו],\u0006 הרי זה באפן מסויים, ו\u0003כגון\u0004 ש\u0003אמר \"והדין\"\u0004 \u0005[וזו]\u0006 \u0003ולא אמר \"נמי\"\u0004 \u0005[גם כן],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? שאולי היתה כוונתו לומר שהערוגה האחרת (\"והדין\") תישאר לו, ולא תיכלל בתוך כל השאר שעושה אותו פאה (תוס').","ותוהים: האם \u0003מכלל\u0004 הדברים, ממה שיש ספק אם כל השאר נעשה פאה, יש להבין \u0003דכי אמר\u0004 \u0005[שאם היה אומר]\u0006 \u0003\"שדה כולה תיהוי\u0004 \u0005[תהיה]\u0006 \u0003פאה\", הויא\u0004 \u0005[הריהי]\u0006 נעשית \u0003פאה?\u0004","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[וכן שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין שאם רוצה לעשות כל שדהו פאה עושה — תלמוד לומר: \"\u0004לא תכלה \u0003פאת שדך\"\u0004 (ויקרא יט, ט) ודרשו שיכול אדם לעשות שיהא כל שדהו (\"שדך\") פאה (\"פאת\").","לאחר הדיון בפרטי ההלכה מבארים את עצם שאלתו של רב פפא. \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דאיתקש\u0004 \u0005[שהוקש,\u0006 הושווה\u0005]\u0006 דין פאה \u0003לקרבנות\u0004 אם כן, נאמר: \u0003מה קרבנות יש להם יד — אף פאה יש לה יד, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כי איתקש\u0004 \u0005[כאשר הוקש]\u0006 דין פאה לקרבנות — \u0003ל\u0004ענין איסור \u0003\"בל תאחר\"\u0004 בלבד \u0003הוא דאיתקש\u0004 \u0005[שהושווה]\u0006 ולא לענין אחר? ומבררים: \u0003והיכא איתקש\u0004 \u0005[והיכן הושווה]\u0006 הדבר? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006:"],["\u0003\"מעמך\"\u0004 בא לרבות דברים שאינם נדר רגיל, \u0003זה לקט שכחה ופאה.\u0004","ועוד שואלים: \u0003יש יד לצדקה, או אין יד לצדקה?\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אילימא דאמר\u0004 \u0005[אם תאמר\u0006 במקרה \u0005ש\u0006הוא \u0005אומר]\u0006 \u0003\"הדין זוזא\u0004 \u0005[זוז זה]\u0006 יהא \u0003לצדקה והדין נמי\"\u0004 \u0005[וזה גם כן]\u0006 אולם \u0003ההוא\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003צדקה עצמה היא! אלא כגון\u0004 ש\u0003אמר \"הדין\"\u0004 \u0005[זה]\u0006 \u0003ולא אמר \"נמי\"\u0004 \u0005[גם כן],\u0006 והשאלה היא: \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם יש לומר כי \u0003\"הדין נמי\u0004 \u0005[זה גם כן]\u0006 יהא \u0003צדקה\" קאמר\u0004 \u0005[\u0006התכוון \u0005לומר],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0005[\u0006\u0003מאי\u0004\u0005]\u0006 \u0003\"והדין\" (נמי)\u0004 \u0005[מה\u0006 פירוש \u0005\"וזה\" גם כן]\u0006 — \u0003לנפקותא בעלמא קאמר\u0004 \u0005[להוצאה סתם\u0006 הוא \u0005שאמר],\u0006 שלאחר שאמר שסלע זה לצדקה אמר שהסלע האחר יהיה להוצאות אחרות, \u0003ודבורא\u0004 \u0005[והדיבור]\u0006 \u0003הוא\u0004 ש\u0003לא אסקיה\u0004 \u0005[השלימו].\u0006","\u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דאיתקש\u0004 \u0005[שהושווה]\u0006 דין צדקה \u0003לקרבנות, דכתיב\u0004 \u0005[שנאמר]\u0006 בפסוק בהמשך דין \"בל תאחר\" של קרבנות \u0003\"\u0004אשר דברת \u0003בפיך\"\u0004 (דברים כג, כד) ודרשו: \u0003זו צדקה.\u0004 ואפשר ללמוד מן ההיקש: \u0003מה קרבנות יש להן יד — אף צדקה יש לה יד. או דלמא\u0004 \u0005[שמא]\u0006 רק \u0003ל\u0004ענין \u0003\"בל תאחר\" הוא דאיתקש\u0004 \u0005[שהושווה]\u0006 ולא לשאר הלכות?","וכן יש לשאול: \u0003יש יד להפקר, או דלמא\u0004 \u0005[שמא]\u0006 \u0003אין יד להפקר?\u0004 האם ביטוי בלתי שלם שעניינו הפקרת רכוש על ידי בעליו, תופס או לא? ושואלים: מה צורך בשאלה מיוחדת זו? \u0003היינו\u0004 \u0005[הרי הוא]\u0006 הדין כמו ב\u0003צדקה!\u0004 שגם צדקה הוא כעין הפקרת ממונו לעניים.","ומשיבים: שאלה זו יש להבין בדרך \u0003\"אם תמצא לומר\" קאמר\u0004 \u0005[אמר]\u0006 כלומר, שאלה זו מתבססת על השאלה הקודמת. וכך כוונת השאלה: \u0003אם תמצא לומר יש יד לצדקה\u0004 והטעם לכך הוא ש\u0003אין היקש למחצה,\u0004 שכיון שהושוותה צדקה לקרבנות לענין \"בל תאחר\", הרי זה היקש והשוואה לכל דבר, אם כן יש לשאול: \u0003הפקר מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 \u0003היינו\u0004 \u0005[הרי הוא]\u0006 כמו \u0003צדקה, או דלמא שאני\u0004 \u0005[שמא שונה]\u0006 \u0003צדקה\u0004 מהפקר, ש\u0003צדקה לא חזיא\u0004 \u0005[אינה ראויה]\u0006 \u0003אלא לעניים\u0004 והיא דומה מצד זה להקדש ומתנות עניים, \u0003אבל הפקר,\u0004 כיון שהוא נתון לכל \u0003בין לעניים בין לעשירים\u0004 אפשר לראותו לא כנתינה אלא כסילוק רשות בלבד, ועל כן אי אפשר ללמוד דין הפקר מדין צדקה?","כיוצא בזה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבינא: יש יד לבית הכסא, או לא?\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אילימא דאמר\u0004 \u0005[אם תאמר\u0006 במקרה \u0005שאומר]\u0006 \u0003\"הדין ביתא ליהוי\u0004 \u0005[בית זה יהא]\u0006 \u0003בית הכסא, והדין נמי\"\u0004 \u0005[וזה גם כן],\u0006 אם כן הבית \u0003ההוא בית הכסא נמי הוה\u0004 \u0005[גם כן נעשה]\u0006 ויש לקיים בו דיני הרחקה לגבי דברים שבקדושה, שהרי זה כמפרש שנקבע גם הבית השני לצורך זה! \u0003אלא\u0004 יש לומר \u0003כגון\u0004 ש\u0003אמר \"והדין\"\u0004 \u0005[וזה]\u0006 \u0003ולא אמר \"נמי\"\u0004 \u0005[גם כן],\u0006 ובמקרה זה יש לשאול: \u0003מאי\u0004 \u0005[מה]\u0006 כוונת \u0003\"הדין\"\u0004 ש\u0003אמר\u0004 האם \u0003\"והדין נמי\u0004 \u0005[וזה גם כן\u0006 יהא\u0005]\u0006 \u0003בית הכסא\", או דלמא\u0004 \u0005[שמא]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"והדין\"\u0004 \u0005[וזה]\u0006 — \u0003לתשמישא בעלמא קאמר\u0004 \u0005[לתשמיש סתם אמר],\u0006 כלומר, שהתכוון לומר שחדר זה מיועד להיות בית הכסא, והשני לצורך אחר.","על עצם השאלה מעירים: האם \u0003מכלל\u0004 הדברים אתה לומד \u0003דפשיטא ליה\u0004 \u0005[שפשוט לו]\u0006 \u0003לרבינא\u0004 ש\u0003יש זימון לבית הכסא\u0004 שברור לו שאם אדם מייעד (מזמן) מקום מסויים להיות בית הכסא — מאותה שעה הריהו נחשב כבית הכסא לכל דיני הרחקה ממנו לגבי דברים שבקדושה, ואין צריך לעשות מעשה? \u0003והא מיבעיא ליה\u0004 \u0005[והרי נסתפקה לו]\u0006 \u0003לרבינא\u0004 השאלה: מקום ש\u0003הזמינו\u0004 בעליו \u0003ל\u0004שמש \u0003בית הכסא מהו\u0004 דינו? וכן מקום ש\u0003הזמינו ל\u0004שמש \u0003בית המרחץ מהו?\u0004 ועיקר השאלה: האם \u0003זימון מועיל,\u0004 כלומר, פועל ומחייב, \u0003או אין זימון מועיל?\u0004 וכיצד רבינא שואל לגבי דין \"יד\" לבית הכסא, כאשר עצם אפשרות הזימון אינה ברורה לו!","ומשיבים: \u0003רבינא חדא מגו חדא\u0004 \u0005[\u0006שאלה \u0005אחת מתוך\u0006 שאלה \u0005אחת,\u0006 אחרת\u0005]\u0006 \u0003קמיבעיא ליה\u0004 \u0005[נשאלה לו].\u0006 כלומר, שאלה זו לענין יד לבית הכסא נובעת משאלה קודמת, שהיה לו ספק עקרוני האם \u0003זימון\u0004 לבית הכסא \u0003מועיל או אין זימון מועיל,\u0004 ואגב כך העלה שאלה נוספת: \u0003אם תמצא לומר\u0004 ותגיע לידי מסקנה ש\u0003יש זימון\u0004 לבית הכסא, יש מקום לשאול \u0003יש יד או אין יד?\u0004 כל השאלות הללו ששאלנו לא נפתרו ונשארו \u0003תיבעי ליה\u0004 \u0005[תשאל לו]\u0006 השאלה. כלומר, השאלה עדיין עומדת במקומה.","שנינו במשנה שהאומר \u0003\"מנודה אני לך\",\u0004 ר' עקיבא היה חוכך בזה להחמיר\". \u0003אמר אביי: מודה ר' עקיבא\u0004 שאם נקט אדם בביטוי זה \u0003לענין מלקות שאינו לוקה\u0004 אם עבר על נדרו. שאף שהיה ר' עקיבא חושש שמא יש כאן נדר, אבל אם עבר על הנדר הזה, אפילו ר' עקיבא מסכים שאינו לוקה מן התורה. ש\u0003אם כן,\u0004 אם היה סבור שהוא נדר ממש, \u0003ניתני\u0004 \u0005[שישנה]\u0006 \u0003\"ר' עקיבא מחמיר\",\u0004 ואילו לשון \"חוכך\" משמעה — לאסור על הנודר מלעבור על נדרו לכתחילה, אבל לא לעונשו אם עבר על נדרו.","\u0003אמר רב פפא:\u0004 אם השתמש \u0003ב\u0004לשון \u0003\"נדינא מינך\" — דכולי עלמא לא פליגי\u0004 \u0005[ל\u0006דעת \u0005הכל אינם חלוקים]\u0006 ש\u0003אסור,\u0004 שיש כאן יד לנדר. ואם השתמש בלשון \u0003\"משמתנא מינך\" — לכולי עלמא שרי\u0004 \u0005[ל\u0006דעת \u0005הכל\u0006 הוא \u0005מותר],\u0006 שאין זו לשון נדר אלא לשון חרם. ואף שודאי היתה כוונתו להרחקה, מכל מקום אין כאן נדר. \u0003במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]\u0006 —"],["\u0003ב\u0004לשון \u0003\"מנודה אני לך\",\u0004 ש\u0003ר' עקיבא סבר: לישנא דנידויא\u0004 \u0005[לשון של\u0006 \u0005נידוי]\u0006 \u0003הוא\u0004 וכוונתו שנודר הנאה ממנו והריהו כמנודה לו, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי \u0003לישנא דמשמתנא\u0004 \u0005[לשון של חרם]\u0006 \u0003הוא,\u0004 שיש בה משמעות של התרחקות, אבל לא נדר ממש.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטה זו על דעת \u0003רב חסדא.\u0004 כפי שמסופר, \u0003דההוא גברא\u0004 \u0005[שאדם אחד]\u0006 ש\u0003אמר \"משמתנא בנכסיה דבריה\u0004 \u0005[משומת אני בנכסים של בנו]\u0006 של \u0003רב ירמיה בר אבא\" אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב חסדא\u0004 לשאול האם אמירה זו יש בה לאסור, או לא. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לית דחש לה להא\u0004 \u0005[אין\u0006 מי \u0005שחושש ל\u0006שיטתו \u0005זו]\u0006 של \u0003ר' עקיבא\u0004 למעשה. ומכאן משמע כי \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 שאף \u0003ב\u0004לשון \u0003\"משמתנא\" פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 שמדבריו נראה שאין מחלוקת התנאים בדיוקי הלשון, אלא בשאלה כללית יותר — אם לשון נידוי או חרם מתפרשת גם לענין נדר.","\u0003אמר ר' אילא אמר רב: נדהו\u0004 את חבירו \u0003בפניו — אין מתירין לו\u0004 את הנידוי \u0003אלא בפניו\u0004 של המנודה. \u0003נדהו שלא בפניו — מתירין לו בין בפניו בין שלא בפניו.\u0004","\u0003אמר רב חנין אמר רב: השומע הזכרת השם\u0004 (שם ה') לבטלה \u0003מפי חבירו — צריך לנדותו\u0004 על כך, \u0003ואם לא נידהו — הוא עצמו\u0004 (השומע) \u0003יהא בנידוי. שכל מקום שהזכרת השם\u0004 לבטלה \u0003מצויה, שם עניות מצויה.\u0004","\u0003ועניות\u0004 דבר קשה הוא מאוד, שהיא נחשבת \u0003כמיתה, שנאמר\u0004 למשה בהיותו במדין: \u0003\"כי מתו כל האנשים\u0004 המבקשים את נפשך\u0003\"\u0004 (שמות ד, יט), וחכמים קיבלו שאנשים אלה היו דתן ואבירם, שעדיין חיו באותו זמן, אלא שירדו מנכסיהם ונחשבים הם בשל כך כמתים. \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל מקום ש\u0004נאמר בו ש\u0003\"נתנו חכמים עיניהם\"\u0004 באדם מסויים, היתה התוצאה מכך \u0003או מיתה או עוני,\u0004 ומכאן משמע גם כן שמיתה ועוני שווים זה לזה.","\u0003אמר ר' אבא: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003רב הונא, שמעה להך איתתא דאפקה\u0004 \u0005[שמע אשה אחת שהוציאה]\u0006 \u0003הזכרת השם לבטלה, שמתה ושרא לה לאלתר באפה\u0004 \u0005[נידה אותה והתיר לה\u0006 את הנידוי \u0005מיד בפניה].\u0006 ומעירים: \u0003שמע מינה תלת\u0004 \u0005[למד מכאן שלשה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003השומע הזכרת השם מפי חבירו צריך לנדותו, ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003נידהו בפניו — אין מתירין לו אלא בפניו, ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 ש\u0003אין בין נידוי להפרה ולא כלום.\u0004 שאין צורך שיחול הנידוי זמן מה, אלא אפשר להפר מיד את הנידוי.","\u0003אמר רב גידל אמר רב: תלמיד חכם מנדה לעצמו\u0004 (את עצמו) אם סבור שעשה דבר שלא כראוי, ומעניש עצמו בכך, \u0003ו\u0004כן \u0003מיפר לעצמו\u0004 את הנידוי. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, מדוע לא יוכל להפר לעצמו כשם שהוא יכול להפר לאחרים? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 כדרך הפתגם המקובל \u0003\"אין חבוש\u0004 (אסיר) \u0003מתיר עצמו מבית האסורין\",\u0004 וכיון שהוא מנודה אינו יכול להתיר לעצמו את הנידוי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף על פי כן יכול לעשות זאת.","ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]\u0006 מקרה כזה שאדם מנדה את עצמו — \u0003כי הא\u0004 \u0005[כמו\u0006 מקרה \u0005זה]\u0006 ש\u0003מר זוטרא חסידא\u0004 \u0005[החסיד]\u0006 \u0003כי מחייב בר בי רב שמתא\u0004 \u0005[כאשר היה מתחייב בן בית הרב,\u0006 תלמיד הישיבה, \u0005נידוי]\u0006 \u0003משמית נפשיה ברישא\u0004 \u0005[\u0006היה \u0005מנדה\u0006 את \u0005עצמו בתחילה]\u0006 \u0003והדר משמת בר בי רב\u0004 \u0005[ואחר\u0006 כך \u0005היה מנדה\u0006 את \u0005בן בית הרב,\u0006 התלמיד\u0005].\u0006 \u0003וכי עייל לביתיה שרי לנפשיה והדר שרי ליה\u0004 \u0005[וכאשר היה בא לביתו\u0006 לאחר הדין \u0005היה מתיר לעצמו\u0006 את הנידוי \u0005ואחר\u0006 כך \u0005היה מתיר לו\u0006 לתלמיד\u0005].\u0006","\u0003ואמר רב גידל אמר רב:\u0004"],["\u0003מנין שנשבעין לקיים את המצוה — שנאמר: \"נשבעתי ואקימה לשמר משפטי צדקך\"\u0004 (תהלים קיט, קו).","ושואלים: מה תוקף יש לשבועה כזו? \u0003והלא מושבע ועומד מהר סיני הוא.\u0004 שכל אדם מישראל מושבע עוד מהר סיני לקיים את כל המצוות, ואין שבועה חלה על שבועה! \u0003אלא הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 שאף שאין לשבועה זו תוקף הלכתי ממש — \u0003דשרי ליה לאיניש לזרוזי נפשיה\u0004 \u0005[שמותר לו לאדם לזרז את עצמו]\u0006 ועל ידי שנשבע הוא מקבל את הדבר על עצמו בתוקף גדול יותר.","\u0003ואמר רב גידל אמר רב: האומר \"אשכים ואשנה פרק זה\"\u0004 או \u0003\"אשנה מסכתא זו\" — נדר גדול נדר לאלהי ישראל.\u0004 כלומר, יש לראות זאת בגדר של נדר, שהוא חייב לקיימו. ושואלים: \u0003והלא מושבע ועומד הוא\u0004 עוד מהר סיני ללמוד תורה, \u0003ואין שבועה חלה על שבועה!\u0004 ואם תאמר: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך, ש\u0003אפילו זרוזי בעלמא\u0004 \u0005[זירוז בלבד]\u0006 יש בכך — אם כן \u0003היינו\u0004 \u0005[הרי זו]\u0006 בדיוק האימרה של \u0003רב גידל קמייתא\u0004 \u0005[הראשונה]\u0006 שאמר שנשבעים לקיים את המצווה!","ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 בכך: \u0003כיון דאי בעי פטר נפשיה\u0004 \u0005[שאם\u0006 היה \u0005רוצה\u0006 היה \u0005פוטר\u0006 את \u0005עצמו]\u0006 מחובת תלמוד תורה שהוא מושבע ועומד עליה מסיני רק \u0003בקרית שמע שחרית וערבית\u0004 ויוצא בכך ידי חובתו, כיון שאמר אשנה \"פרק זה\" או \"מסכת זו\" \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003חייל\u0004 \u0005[חלה]\u0006 ה\u0003שבועה עליה\u0004 \u0005[עליו]\u0006 על אותו דבר שפירש.","ובאותו ענין \u0003אמר רב גידל אמר רב: האומר לחבירו \"נשכים ונשנה פרק זה\"\u0004 והסכימו על כך — \u0003עליו להשכים\u0004 ולבוא תחילה, שכיון שהוא הזמין את החבר — עליו להיות שם קודם, ורמז לדבר, ממה \u0003שנאמר: \"ויאמר אלי (בן אדם) קום צא אל הבקעה ושם אדבר אותך.\u0004 ואקום \u0003ואצא אל הבקעה והנה שם כבוד ה' עמד\"\u0004 (יחזקאל ג, כב-כג). שהזמין הקדוש ברוך הוא את יחזקאל לאותו מקום, והוא עצמו כביכול היה שם קודם.","\u0003אמר רב יוסף:\u0004 מי ש\u0003נידוהו בחלום, צריך\u0004 להביא \u0003עשרה בני אדם להתיר לו\u0004 את הנידוי הזה, \u0003והוא\u0004 שיהיו האנשים הללו שהוא מזמין \u0003דתנו הלכתא\u0004 \u0005[ששנו הלכה],\u0006 כלומר, שהם בגדר תלמידי חכמים, \u0003אבל\u0004 אלה שרק \u0003מתנו\u0004 \u0005[שנו\u0006 משנה\u0005]\u0006 \u0003ולא תנו\u0004 \u0005[שנו]\u0006 עדיין גמרא — \u0003לא,\u0004 אינם מספיקים לכך. \u0003ואי ליכא\u0004 \u0005[ואם אין]\u0006 \u0003דתנו הלכתא אפילו מתנו ולא תנו.\u0004","\u0003ואי ליכא\u0004 \u0005[ואם אין]\u0006 הוא יכול לאסוף עשרה אנשים כאלה — \u0003ליזיל וליתב\u0004 \u0005[שילך וישב]\u0006 על \u0003פרשת\u0004 (צומת) \u0003דרכים ויהיב שלמא לבי עשרה\u0004 \u0005[ויתן שלום לעשרה אנשים]\u0006 וישיבו לו שלום, והרי זה כהתרת הנידוי במקצת, \u0003עד דמקלעי ליה\u0004 \u0005[שיזדמנו לו]\u0006 מבין העוברים \u0003עשרה דגמרי הלכתא\u0004 \u0005[שלמדו הלכה]\u0006 והם מצטרפים יחד להתירו לגמרי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 אם \u0003ידע מאן שמתיה\u0004 \u0005[יודע מי נידה אותו]\u0006 בחלומו, \u0003מהו דלישרי ליה\u0004 \u0005[האם\u0006 יכול אותו אחד שנידהו גם \u0005להתיר לו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לשמותיה\u0004 \u0005[לנדות אותו]\u0006 — \u0003שויוה\u0004 \u0005[עשו אותו\u0006 אדם\u0005]\u0006 \u0003שליח\u0004 משמים, אבל \u0003למישרי ליה\u0004 \u0005להתיר לו]\u0006 \u0003לא שויוה\u0004 \u0005[עשו אותו]\u0006 \u0003שליח,\u0004 ולכך אין כוחו יפה, וצריך עשרה שיתירוהו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא לרב אשי: שמתיה ושרו ליה בחלמיה, מאי\u0004 \u0005[\u0006אם \u0005נידו אותו והתירו לו ב\u0006תוך \u0005חלומו, מה\u0006 הדין\u0005],\u0006 האם אפשר לומר שכבר הותר לו הנידוי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 כלל הוא בידינו: \u0003כשם שאי אפשר לבר\u0004 (תבואה) \u0003בלא תבן\u0004 (קש, פסולת התבואה),"],["\u0003כך אי אפשר לחלום\u0004 שיהיה \u0003בלא דברים בטלים,\u0004 וייתכן איפוא שהנידוי היה בו ממש, אבל ההיתר היה מן הדברים הבטלים שבחלום, ולכן צריך הוא התרה נוספת.","מסופר: \u0003רבינא הוה\u0004 \u0005[היה]\u0006 \u0003לה נדרא לדביתהו\u0004 \u0005[נדר לאשתו]\u0006 שהוא עצמו לא הפר אותו כבעלה, והיא רצתה להתירו. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 רבינא \u0005לפני]\u0006 \u0003רב אשי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בעל מהו שיעשה שליח לחרטת אשתו,\u0004 האם יכול הבעל להיות שליח לומר שאשתו מתחרטת על הנדר, ויתירו לה חכמים את הנדר על ידי שליחות זו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי מכנפין\u0004 \u0005[אם מכונסים]\u0006 יחד שלושה אנשים שיכולים להתיר לה את נדרה — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא — לא\u0004 יוכל להיות שליח להתיר את נדרה.","ומעירים: \u0003שמע מינה תלת\u0004 \u0005[למד מכאן,\u0006 מפסק זה, \u0005שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003בעל\u0004 אכן \u0003נעשה שליח לחרטת אשתו, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003לא שרי למישרי נדרא באתרא דרביה\u0004 \u0005[אין מותר\u0006 לחכם \u0005להתיר נדרים במקום\u0006 בו נמצא \u0005רבו],\u0006 שאם לא כן היה רבינא עצמו שהיה חכם חשוב יכול להתיר לאשתו את נדרה. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003כי מכנפין —\u0004 \u0005[כאשר מכונסים]\u0006 שלושה \u0003שפיר דמי\u0004 \u0005[\u0006הרי זה \u0005יפה,\u0006 מספיק\u0005],\u0006 כדי שיהיה הבעל שליח לחרטה. אך אם יש צורך לאסוף אנשים במיוחד לצורך כך, אין מתירים.","ומוסיפים: \u0003ושמתא\u0004 \u0005[ונידוי]\u0006 — \u0003אפילו באתרא דרביה\u0004 \u0005[במקום\u0006 בו נמצא \u0005רבו]\u0006 יכול התלמיד להתיר כשמצרף לו עוד שניים, \u0003ו\u0004דיין \u0003יחיד\u0004 אם הוא \u0003מומחה שרי שמתא\u0004 \u0005[\u0006הריהו \u0005מתיר חרם]\u0006 לבדו.","\u0003אמר ר' שמעון בר זביד, אמר ר' יצחק בר טבלא, אמר ר' חייא אריכא דבי\u0004 \u0005[מבית]\u0006 \u0003ר' אחא, אמר ר' זירא, אמר ר' אלעזר, אמר ר' חנינא, אמר ר' מיאשה משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יהודה בר אילעאי,\u0004 ומה מסרו בשלשלת חכמים זו: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"וזרחה לכם יראי שמי\" (שמש צדקה\u0004 ומרפא בכנפיה \u0003\")\u0004 (מלאכי ג, כ) \"יראי שמי\" — \u0003אלו בני אדם שהן יראין להוציא שם שמים לבטלה — \"שמש צדקה ומרפא\"\u0004 בשבילם. \u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003חרגא דיומא מסי\u0004 \u0005[אבק של היום,\u0006 הנראה בקרני השמש, \u0005מרפא],\u0006 שכן נאמר \"שמש צדקה ומרפא בכנפיה\".","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003ר' שמעון בן לקיש,\u0004 ש\u0003אמר: אין גיהנם לעולם הבא, אלא הקדוש ברוך הוא מוציא חמה מנרתיקה,\u0004 מן הכיסוי שהיא מצויה בו בזמן הזה ואינה מגולה, \u0003צדיקין מתרפאין בה\u0004 באותה חמה \u0003ורשעים נידונין בה.\u0004 צדיקים מתרפאים בה, \u0003שנאמר: \"וזרחה לכם יראי שמי שמש\u0004 צדקה ומרפא \u0003\". ולא עוד,\u0004 לא רק שהם מתרפאים בה, \u0003אלא\u0004 אף \u0003שמתעדנין בה, שנאמר: \"ויצאתם ופשתם כעגלי מרבק\"\u0004 (מלאכי ג, כ).","\u0003והרשעים נידונין בה\u0004 באותה שמש, \u0003שנאמר: \"הנה היום בא בער כתנור\u0004 והיו כל זדים וכל עושה רשעה קש, וליהט אותם היום הבא\u0003\"\u0004 (מלאכי ג, יט). ומכאן שלדעת ר' שמעון בן לקיש אין השמש מרפאה, אלא לעתיד לבוא. ולא כדברי אביי המפרש את הפסוק על הזמן הזה."],["אם אמר אדם שהוא מקבל על עצמו \u0003\"כנדרי רשעים\" —\u0004 הרי באותה אמירה \u0003נדר בנזיר ובקרבן ובשבועה,\u0004 שכן דרכם של רשעים שמרבים לנדור נדרים שונים, והרי זה בכלל ידות והועילו לו דבריו כאילו פירש נדרו. ואולם אם אמר \u0003\"כנדרי כשרים\" — לא אמר כלום,\u0004 לפי שכשרים אינם נודרים ואינם נשבעים. אם אמר \u0003\"כנדבותם\u0004 של כשרים \u0003\"\u0004— יש בכך ממש, והכוונה היא ש\u0003נדר בנזיר ובקרבן,\u0004 שאף כשרים מתנדבים בדברים אלו.","על הקטע הראשון במשנה העוסק במי שאמר \"כנדרי רשעים\", שואלים: \u0003ודלמא הכי קאמר\u0004 \u0005[ושמא כך\u0006 היתה כוונתו \u0005לומר]:\u0006 \u0003כנדרי רשעים לא נדרנא\u0004 \u0005[אינני נודר]?\u0006 ואם כן לא החיל על עצמו כל נדר! \u0003אמר שמואל:\u0004 מדובר \u0003באומר \"כנדרי רשעים הריני עלי והימנו\"\u0004 ולשון זו כוללת את כל ההתחייבויות, כי כאשר אמר \u0003\"הריני\"\u0004 — כוונתו \u0003בנזירות,\u0004 וכשאמר \u0003\"עלי\"\u0004 — משמע שקיבל עליו הדבר \u0003בקרבן,\u0004 וכשאמר \u0003\"הימנו\"\u0004 — כוונתו שהוא נדור ממנו \u0003בשבועה.\u0004","ומבררים את הדברים: אמרנו כי כשאומר \u0003\"הריני\"\u0004 הרי זו \u0003נזירות.\u0004 ושואלים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003הריני בתענית קאמר\u0004 \u0005[אמר]?\u0006 \u0003אמר שמואל:\u0004 כאן אין מדובר שאמר \"כנדרי רשעים הריני\" סתם, אלא \u0003כשהיה נזיר עובר לפניו\u0004 ומשמעות דבריו מובנת לפי ההקשר.","ועוד אמרנו שם ש\u0003\"עלי\" — בקרבן, \"הימנו\" — בשבועה.\u0004 ושואלים: מדוע נאמר ש\"הימנו\" כוונתו לאסור עליו את הדבר בשבועה? \u0003דלמא\u0004 \u0005[שמא]\u0006 נפרש בדרך אחרת: \u0003\"הימנו\" — דאכילנא קאמר\u0004 \u0005[שאני אוכל\u0006 אותו \u0005אמר],\u0006 שקיבל על עצמו בשבועה לאוכלו, וכאשר יאכל את הככר יקיים שבועתו! \u0003אמר רבא:\u0004 יש לפרש ש\u0003אמר \"הימנו שלא אוכל\".\u0004","ומקשים: אם פירש ואמר בסגנון זה, \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך מה\u0006 בא \u0005לומר]?\u0006 שלפי זה אין חידוש בדבר, שהרי פירש את דבריו לאיסור! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא מפיק\u0004 \u0005[מוציא]\u0006 לשון \u0003שבועה מפומיה\u0004 \u0005[מפיו]\u0006 אלא אמר רק \"כנדרי רשעים הימנו שלא אוכל\", ולא אמר שנודר או נשבע, על כן \u0003קא משמע לן הדין\u0004 \u0005[השמיע לנו\u0006 דבר \u0005זה]\u0006 שיש כאן יד לשבועה.","שנינו במשנה: \u0003\"כנדרי כשרים\" — לא אמר כלום, \"כנדבותם\" — נדר\u0004 בנזיר ובקרבן. ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דשאני ליה\u0004 \u0005[ששונה לו],\u0006 שיש לדעתו הבדל לענין האיסור שבדבר \u0003בין נדר לנדבה? לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 שאין זו \u0003לא\u0004 דעת \u0003ר' מאיר ולא\u0004 דעת \u0003ר' יהודה?\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 בביאור הכתוב \u0003\"טוב אשר לא תדר\u0004 משתדור ולא תשלם\u0003\"\u0004 (קהלת ה, ד) הוסיפו חכמים: \u0003טוב מזה ומזה — שאינו נודר כל עיקר,\u0004 אלו \u0003דברי ר' מאיר.\u0004 ואילו \u0003ר' יהודה אומר: טוב מזה ומזה נודר ומשלם.\u0004 ומדבריהם עולה כי לדעת ר' מאיר כל נדר ונדבה יש בו איסור מסויים, ולדעת ר' יהודה הנודר ומקיים אין בו איסור. ולדברי שניהם אין הבדל בין נדר ונדבה. ואם כן, משנתנו, האומרת שאין הכשרים נודרים נדר אבל נודבים נדבה, כשיטת מי היא?","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כדעת \u0003ר' מאיר,\u0004"],["\u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' מאיר\u0004 שיש בכך איסור, הרי זה — \u0003בנדר, בנדבה לא קאמר\u0004 \u0005[אמר].\u0006 ומקשים: \u0003והא קתני\u0004 \u0005[והרי שנה\u0006 במשנה\u0005]:\u0006 \u0003\"כנדבותם\" — נדר בנזיר ובקרבן,\u0004 משמע שנדר קרבן הוא נדר של כשרים! ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 ותקן את הלשון: \u0003נדב בנזיר ובקרבן.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003נודר\u0004 האומר \"הרי עלי קרבן\" ש\u0003לא\u0004 ראוי לעשות כן משום שיש בו חשש \u0003דלמא אתי\u0004 \u0005[שמא בא]\u0006 \u0003בה,\u0004 באמירה זו, \u0003לידי תקלה,\u0004 שהרי חייב עצמו מיד בנדר, ושמא לא יביאנו בזמנו ועובר משום \"בל תאחר\". אולם \u0003נדבה\u0004 שאמר \"בהמה זו לקרבן\" \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יעשה, \u0003דלמא אתי\u0004 \u0005[שמא בא]\u0006 \u0003בה לידי תקלה.\u0004 שהרי בהמה זו מוקדשת, וכל הנהנה ממנה בשגגה, כשגוזזה או כשעובד בה, עובר משום מעילה!","ומשיבים: בנדבה יכול לעשות \u0003כהלל הזקן. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו על הילל הזקן שלא מעל אדם בעולתו\u0004 (בקרבן עולה שלו) \u0003כל ימיו.\u0004 כיצד? היה \u0003מביאה,\u0004 את הבהמה, \u0003כשהיא חולין לעזרה, ו\u0004שם היה \u0003מקדישה, ו\u0004מיד \u0003סומך עליה ושוחטה.\u0004 ולכן לא היה מקום למעילה, שהרי קודם שהביאה לעזרה היתה זו בהמת חולין. ואם כן אפשר לעשות נדבה כזו בלא חשש לתקלה.","ומקשים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 ב\u0003נדבה\u0004 של \u0003קרבנות,\u0004 שיכול להביאה בלי לגרום לתקלה. אבל \u0003נדבה\u0004 של \u0003נזירות מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי יש חשש שיבוא לידי תקלה, שלא יוכל לקיים נזירותו! ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כשמעון הצדיק.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר (ר') שמעון הצדיק: מימי לא אכלתי\u0004 בתור כהן \u0003אשם\u0004 שמביא \u0003נזיר טמא אלא אחד.\u0004 שהיה חושש שהנזיר עשה נדר זה מחמת כעס או הקפדה ובעצם אין ליבו שלם עם הנזירות, וביותר הוא מתחרט על נזירותו כאשר נטמא, וצריך להביא קרבנות נוספים ושוב לנהוג נזירות. וכך היה מעשה: \u0003פעם אחת בא אדם אחד נזיר מן הדרום, וראיתיו שהוא יפה עינים וטוב רואי\u0004 (יפה מראה) \u0003וקווצותיו\u0004 (קווצות שערותיו) \u0003סדורות לו תלתלים. אמרתי לו: בני, מה ראית להשחית את שערך זה הנאה\u0004 על ידי זה שנדרת נזירות, ועכשיו אתה מגלח את שערך?","\u0003אמר לי: רועה הייתי לאבא בעירי, הלכתי למלאות מים מן המעיין ונסתכלתי בבבואה שלי\u0004 (בדמותי המשתקפת במים) \u0003ופחז\u0004 (מיהר, גבר) \u0003עלי יצרי ובקש לטורדני\u0004 (לאבדני) \u0003מן העולם,\u0004 שראה כמה הוא יפה, ועלתה בו מחשבה להשתמש ביופיו למטרות שאינן כשרות. \u0003אמרתי לו\u0004 ליצרי: \u0003רשע! למה אתה מתגאה בעולם שאינו שלך,\u0004 ולמה אתה מתגאה בגוף \u0003במי שהוא עתיד להיות\u0004 מאכל בקבר ל\u0003רמה ותולעה? העבודה\u0004 כלומר, נודר אני בעבודת המקדש \u0003שאגלחך לשמים!\u0004 כך אמר לו אותו אדם.","וסיפר שמעון הצדיק: \u0003מיד עמדתי ונשקתיו על ראשו, אמרתי לו: בני, כמוך ירבו נוזרי נזירות בישראל. עליך הכתוב אומר \"איש\u0004 או אשה \u0003כי יפלא לנדר נדר נזיר להזיר לה'\"\u0004 (במדבר ו, ב). כלומר, שהוא נדר מופלא וברור שכל כולו לה', שאין בו ענין של כעס או נסיון להרגיז, אלא כל כולו לה'. משמע שיש אופן של נזירות שכולו בכשרות וזאת היא נדבה שבנזירות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על גופו של אותו מעשה \u0003ר' מני: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003אשם נזיר טמא\u0004 ש\u0003לא אכל\u0004 שמעון הצדיק מימיו — מפני \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003על חטא\u0004 שחטא אותו אדם בזה שנטמא? \u0003כל אשמות נמי\u0004 \u0005[גם כן]\u0006 ש\u0003לא ליכול\u0004 \u0005[יאכל],\u0006 שכן אף הם \u0003על חטא אתו\u0004 \u0005[\u0006הם \u0005באים]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יונה: היינו טעמא\u0004 \u0005[זהו הטעם\u0006 בנזירות\u0005];\u0006 \u0003כשהן תוהין,\u0004 טועים בדבר וכועסים על דבר, הם \u0003נוזרין. וכשהן מטמאין, ורבין עליהן ימי נזירות מתחרטין בהן.\u0004 וכיון שהתחרט הנזיר על הנדר מעיקרו נמצא שבאמת בטל הנדר ואין כאן נזירות, \u0003ונמצאו מביאין חולין לעזרה,\u0004 כלומר, אותם קרבנות שנתחייבו בנזירותם.","ושואלים: אם חשש שמעון הצדיק שהנזיר עלול להתחרט על נזירותו, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו\u0004 אשמו של \u0003נזיר טהור נמי\u0004 \u0005[גם כן]\u0006 לא ייאכל! ומשיבים: \u0003נזיר טהור לא,\u0004 אין לחשוש בו, משום \u0003דאמודי אמיד נפשיה\u0004 \u0005[שהעריך את עצמו]\u0006 ש\u0003יכול לנדור\u0004 (לנזור) מיין ומשאר דברים האסורים לנזיר במשך זמן מסויים, ומן הסתם לא התחרט. אבל נזיר טמא שתקלה אירעה לו, ונמשכו ימי נזירותו יותר מששיער מלכתחילה — יש מקום לחשש שהתחרט.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 לגופה של השאלה ששאלנו על משנתנו, כשיטת איזה מן התנאים נאמרה:"],["\u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו היא כשיטת \u0003ר' יהודה\u0004 יש להבדיל, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יהודה\u0004 שטוב הנודר ומקיים — \u0003בנדבה\u0004 אמר, \u0003בנדר לא אמר.\u0004","ומקשים: \u0003והקתני\u0004 \u0005[והרי שנה]\u0006 בלשון ר' יהודה לשון נדר: \u0003\"טוב מזה ומזה נודר ומקיים\"!\u0004 ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 ותקן בלשון ר' יהודה: \u0003\"נודב ומקיים\".\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003נודר\u0004 ש\u0003לא,\u0004 שאינו טוב, \u0003דילמא אתי\u0004 \u0005[שמא יבוא]\u0006 \u0003בה לידי תקלה\u0004 שיעבור ב\"בל תאחר\", \u0003נדבה נמי\u0004 \u0005[גם כן]\u0006 יש בה חשש \u0003דילמא אתי\u0004 \u0005[שמא יבוא]\u0006 \u0003בה לידי תקלה\u0004 של מעילה!","ומשיבים: \u0003ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר\u0004 במפורש: \u0003אדם מביא כבשתו לעזרה ומקדישה\u0004 שם, \u0003וסומך עליה ושוחטה,\u0004 ואם כן אין חשש שיבוא לידי תקלה של מעילה בקודשים.","שואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 תשובה זו יפה בענין \u0003נדבה\u0004 של \u0003קרבנות,\u0004 ואולם \u0003נדבה\u0004 של \u0003נזירות מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי יש לחשוש לתקלה!","ומשיבים: גם בזה \u0003ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: חסידים הראשונים היו מתאוין להביא קרבן חטאת,\u0004 אלא שלא נזדמן להם \u0003לפי שאין הקדוש ברוך הוא מביא תקלה על ידיהם\u0004 ולא היו חוטאים אף לא בשגגה, \u0003מה היו עושין? עומדים ומתנדבין נזירות למקום\u0004 (לה'), \u0003כדי שיתחייב קרבן חטאת\u0004 של נזיר \u0003למקום.\u0004","\u0003ר' שמעון אומר: לא נדרו בנזיר, אלא\u0004 כך היו עושים: \u0003הרוצה להביא עולה — מתנדב ומביא,\u0004 הרוצה להביא \u0003שלמים — מתנדב ומביא,\u0004 הרוצה להביא \u0003תודה וארבעה מיני לחמה — מתנדב ומביא. אבל בנזירות לא התנדבו, כדי שלא יקראו חוטאין.\u0004 שלדעתו בעצם הנזירות יש צד של חטא, \u0003ש\u0004כן \u0003נאמר \"וכפר עליו מאשר חטא על הנפש\"\u0004 (במדבר ו, יא), ולכן לא נדרו בנזיר, כדי שלא ייחשבו כחוטאים אף במעט.","\u0003אמר אביי: שמעון הצדיק ור' שמעון ור' אלעזר הקפר — כולן שיטה אחת הן,\u0004 שהם סבורים ש\u0003נזיר חוטא הוי\u0004 \u0005[הוא],\u0006 שעצם הנזירות יש בה צד חטא. ומפרט: \u0003שמעון הצדיק ורבי שמעון — הא דאמרן\u0004 \u0005[זה שאמרנו].\u0006","\u0003ו\u0004גם \u0003ר' אלעזר הקפר ברבי\u0004 סבור כן, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר הקפר ברבי אומר:\u0004 נאמר על נזיר \u0003\"וכפר עליו מאשר חטא על הנפש\"\u0004 (במדבר ו, יא). ועל כך יש לשאול: \u0003וכי באיזו נפש חטא זה\u0004 הנזיר? \u0003אלא\u0004 יש לבאר: חטאו הוא על \u0003שציער עצמו מן היין,\u0004 וחטא בכך על הנפש — על נפשו שלו, שציער את עצמו לחינם. \u0003והלא דברים קל וחומר: ומה זה\u0004 (נזיר) \u0003שלא ציער עצמו אלא מן היין נקרא חוטא, המצער עצמו מכל דבר\u0004 ודבר \u0003על אחת כמה וכמה\u0004 שנקרא חוטא. \u0003מכאן\u0004 יש ללמוד כי \u0003כל היושב בתענית נקרא חוטא.\u0004","ושואלים על שיטת ר' אלעזר הקפר: \u0003והדין קרא\u0004 \u0005[ו\u0006הלא \u0005כתוב זה]\u0006 \u0003בנזיר טמא כתיב\u0004 \u0005[נאמר]\u0006 ולא בנזיר טהור, ואם כן אפשר לפרש שדווקא הנזיר הטמא הוא זה שנקרא חוטא, שחטא על הנפש במה שנטמא! ומשיבים: ר' אלעזר הקפר סבור שהיה הדבר ראוי להיאמר גם בנזיר טהור, ומפני מה נאמר בנזיר טמא \u0003משום\u0004 ש\u0003שנה\u0004 (חזר וכפל) \u0003בחטא הוא,\u0004 שלא די לו שחטא בזה שנדר נזירות אלא עוד הוסיף וחטא בזה שנטמא, ולכן נאמר דווקא בו \"מאשר חטא על הנפש\".","\u0003האומר (לחבירו)\u0004 לשון זו שדבר מסויים יהא \u0003\"קונם\"\u0004 או \u0003\"קונח\"\u0004 או \u0003\"קונס\" — הרי אלו\u0004 הלשונות \u0003כינויין לקרבן,\u0004 וכאמור כל כינויי נדרים הם כנדרים. האומר \u0003\"חרק\"\u0004 או \u0003\"חרך\"\u0004 או \u0003\"חרף\" — הרי אלו כינויין לחרם.\u0004 האומר \u0003\"נזיק\"\u0004 או \u0003\"נזיח\"\u0004 או \u0003\"פזיח\" — הרי אלו כינויין לנזירות.\u0004 האומר \u0003\"שבותה\"\u0004 או \u0003\"שקוקה\"\u0004 או \u0003נודר ב\"מוהי\" — הרי אלו כינויין לשבועה,\u0004 ששבועה נקראת בארמית \"מומתא\", והכינוי לכך הוא \"מוהי\".","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים במהות ה\u0003כינויין, ר' יוחנן אמר: לשון אומות הן,\u0004 שיש עמים שבהם משמשות לשונות אלה לקרבן או לחרם או לנזיר או לשבועה. \u0003ר' שמעון בן לקיש אמר:\u0004 לשון זו היא \u0003לשון שבדו\u0004 (שיצרו) \u0003להם חכמים\u0004 לבני האדם כדי \u0003להיות נודר בו\u0004 כל הרוצה בכך. וכדי להסביר לשון \"בדא\" הוא מביא מן המקרא: \u0003וכן הוא אומר\u0004 בירבעם \u0003\"בחדש אשר בדא מלבו\"\u0004 (מלכים א יב, לג), שמשמעו — המציא. כלומר, אלה הם לשונות שהמציאו חכמים לצורך זה.","\u0003ו\u0004לשיטתו \u0003טעמא מאי תקינו רבנן\u0004 \u0005[מה טעם תיקנו חכמים]\u0006 \u0003כינויין\u0004 אלה? — ש\u0003לא לימא\u0004 \u0005[יאמר]\u0006 הנודר במפורש \u0003\"קרבן\".\u0004 ושואלים: \u0003ולימא\u0004 \u0005[ויאמר]\u0006 \u0003\"קרבן\"\u0004 ומה לא טוב בכך? ומשיבים: \u0003דילמא אמר\u0004 \u0005[שמא יאמר]\u0006 \u0003\"קרבן לה'\".\u0004 ותוהים גם על כך: \u0003ולימא\u0004 \u0005[ויאמר]\u0006 \u0003\"קרבן לה'\"!\u0004 ומשיבים: \u0003דילמא אמר\u0004 \u0005[שמא\u0006 יבוא ו\u0005יאמר]\u0006 \u0003\"לה'\"\u0004 ויתחרט \u0003ולא אמר\u0004 \u0005[יאמר]\u0006 אחר כך \u0003\"קרבן\", וקא מפיק\u0004 \u0005[ו\u0006נמצא על ידי כך \u0005מוציא]\u0006 \u0003שם שמים לבטלה\u0004","\u0003ו\u0004כיוצא בו \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004"],["\u0003מנין שלא יאמר אדם \"לה' עולה\", \"לה' מנחה\", \"לה' תודה\", \"לה' שלמים\" — תלמוד לומר: \"קרבן לה'\"\u0004 (ויקרא א, ב), שיקדים ויאמר \"קרבן\", שאם יאמר \"לה' קרבן\" שמא לא יסיים את דיבורו ולא יהיה בכך משום הקדשת קרבן, ונמצא מוציא שם שמים לבטלה.","\u0003וקל וחומר: ומה זה שלא נתכוון אלא להזכיר שם שמים על הקרבן — אמרה תורה\u0004 שידקדק ויאמר \u0003\"קרבן לה'\",\u0004 מי שמזכיר שם שמים \u0003לבטלה — על אחת כמה וכמה\u0004 שעובר עבירה חמורה.","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שמחלוקת זו של ר' יוחנן וריש לקיש \u0003כ\u0004מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 היא, ששנינו, \u0003בית שמאי אומרים: כינויי כינויין\u0004 — \u0003אסורין.\u0004 שאם אמר כינויים שאינם אלה המפורשים במשנה, אלא ביטויים אחרים הדומים להם — אף הם אוסרים משום נדר. \u0003ובית הלל אומרים: כינויי כינויין\u0004 — \u0003מותרין.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 צריך לפרש כך: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003כינויי כינויין אסורין, קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003(כינויי) כינויין לשון אומות הן,\u0004 ולכן כינויי כינויים הדומים להם אף הם אסורים. \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003מותרים, קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 שכינויים עצמם הם \u0003לשון שבדו\u0004 (יצרו) \u0003להן חכמים,\u0004 והם קבעו רק מילים מסויימות ולא מילים אחרות, אף שהן דומות להן?","ודוחים: \u0003לא,\u0004 אפשר לפרש כי \u0003דכולי עלמא\u0004 \u0005[שהכל]\u0006 סבורים כי \u0003כינויין\u0004 עצמם \u0003לשון אומות הן, ו\u0004יש להסביר את המחלוקת כך: \u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 כי \u0003בהני נמי משתעי\u0004 \u0005[באלה,\u0006 כינויי כינויים \u0005גם כן מדברים]\u0006 \u0003אומות, ובית הלל סברי\u0004 \u0005[סבורים]\u0006 כי \u0003בהני\u0004 \u0005[באלה]\u0006 \u0003לא משתעי\u0004 \u0005[מדברים]\u0006 \u0003אומות.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: כינויים עצמם לשון אומות הם, אלא \u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 כי \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003כינויי כינויין משום כינויין,\u0004 ואוסרים גם בהם. \u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 ש\u0003לא גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003כינויי כינויין משום כינויין.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הם\u0006 בדיוק\u0005]\u0006 \u0003כינויי כינויין\u0004 של \u0003נדרים? תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף,\u0004 אלה הם: \u0003\"מקנמנא\" \"מקנחנא\" \"מקנסנא\".\u0004 שבונה פועל מן המלה שהיא כינוי לקרבן. ועוד שואלים: \u0003היכי דמי\u0004 \u0005[כיצד הם\u0006 בדיוק\u0005]\u0006 \u0003כינויי כינויין\u0004 של \u0003חרם? תני\u0004 \u0005[שנה]\u0006 החכם \u0003מפשאה: \"חרקים\" \"חרכים\" \"חרפים\".\u0004 ועוד: מה הם \u0003כינויי כינויין\u0004 של \u0003נזירות? תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: \"מחזקנא\" \"מנזחנא\" \"מפיחנא\".\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה ללומדים\u0005]:\u0006 האומר לשון מסובכת יותר \u0003\"מיפחזנא\" מאי\u0004 \u0005[מה]\u0006 הדין? \u0003\"מיתחזנא\" מאי\u0004 \u0005[מה]\u0006 דינו? \u0003\"מיתעזנא\" מאי\u0004 \u0005[מה]\u0006 יהא דינו? וכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 אם אמר \u0003\"קינמא\" (קינמא) מאי\u0004 \u0005[מה]\u0006 דינו? וצדדי השאלה: האם לשון \u0003\"קונם\" קאמר\u0004 \u0005[אומר]\u0006 ורק שינה את הלשון, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003\"קנמן בשם\"\u0004 (שמות ל, כג) \u0003קאמר\u0004 \u0005[אמר,\u0006 התכוון\u0005]\u0006 ולא התכוון כלל לקונם?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חייא לרב אשי:\u0004 אם אמר \u0003\"קינה\" מאי\u0004 \u0005[מה]\u0006 היתה כוונתו? האם \u0003קינה\u0004 (קן) \u0003תרנגולין קאמר\u0004 \u0005[אומר],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לשון\u0004 של \u0003קונם?\u0004 לכל השאלות האלה לא נמצאה תשובה, ומשאירים את השאלה ב\u0003תיבעי\u0004 \u0005[תישאל]\u0006 השאלה במקומה.","ועוד שואלים: \u0003כינויי כינויין\u0004 של \u0003שבועה היכי דמי\u0004 \u0005[כיצד הם בדיוק]?\u0006 ומשיבים: \u0003\"שבואל\" \"שבותיאל\" \"שקוקאל\".\u0004 ושואלים: מדוע נאמר כן על לשון \u0003שבואל?\u0004 הלא \u0003שבואל בן גרשום משמע,\u0004 שם פרטי הוא, ומדוע נאמר שהוא כינוי לשבועה! \u0003אלא\u0004 כך היתה השאלה: האומר \u0003\"שבובאל\" \"שבותיאל\" \"שקוקאל\" מהו\u0004 דינו? \u0003אמר שמואל:\u0004 אם \u0003אמר \"אשיבתא\"\u0004 אף על פי שיש בו מעין דמיון לכינוי של שבועה — \u0003לא אמר כלום, \"אשקיקא\" — לא אמר כלום, \"קרינשא\" —\u0004 הדומה קצת לקונם — \u0003לא אמר כלום.\u0004","שנינו: \u0003\"נדר במוהי הרי אלו כינויין\". תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: האומר \"במוהי\"\u0004 — \u0003לא אמר כלום,\u0004 לפי שאין משמעות ללשון \"מוהי\", אבל אם אמר \u0003\"במומתא\u0004 \u0005[בשבועה]\u0006 ש\u0003אמר מוהי\"\u0004 — \u0003הרי אלו כינויין לשבועה.\u0004","\u0003האומר \"לחולין שאוכל לך\"\u0004 שמתפרש כמו \"לא חולין\" = אינו חולין (כלומר, קודש הוא) יהא מה שאוכל משלך, או שאמר \u0003\"לא כשר\" ו\"לא דכי\",\u0004 שפירושו לא \u0003\"טהור\", ו\"טמא\", \"נותר\" ו\"פיגול\" —\u0004 הרי זה \u0003אסור.\u0004","\u0003כאימרא\u0004 \u0005[כשה\u0006 של תמיד\u0005],\u0006 \u0003כדירים\u0004 של בהמות הקרבן, \u0003כעצים\u0004 של מזבח, \u0003כאשים, כמזבח, כהיכל, כירושלים.\u0004 או \u0003נדר באחד מכל משמשי המזבח, אף על פי שלא הזכיר\u0004 במפורש שם \u0003קרבן — הרי זה נדר בקרבן. ר' יהודה אומר: האומר \"ירושלים\" לא אמר כלום.\u0004"],["\u0003א גמרא סברוה\u0004 \u0005[סברו\u0006 הלומדים\u0005]\u0006 מתחילה: \u0003מאי\u0004 \u0005[מה\u0006 לשון\u0005]\u0006 \u0003\"לחולין\" —\u0004 כוונתו \u0003לא לחולין ליהוי\u0004 \u0005[יהיה],\u0006 \u0003אלא קרבן.\u0004 שמתוך השלילה אנו מבינים שכוונתו שהדבר הזה יהיה כהקדש.","ונברר: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי\u0006 היא \u0005משנתנו]?\u0006 \u0003אי\u0004 \u0005[אם\u0006 תאמר\u0005]\u0006 שהיא כשיטת \u0003ר' מאיר —\u0004 הלא ר' מאיר \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את ההנחה ש\u0003מכלל לאו\u0004 \u0005[לא]\u0006 \u0003אתה שומע הן\u0004 \u0005[כן].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' מאיר אומר: כל תנאי שאינו כתנאי בני גד ובני ראובן\u0004 שהתנה עימם משה כאשר נתן להם את עבר הירדן (במדבר לב, כט-ל), שהוא תנאי כפול, שמפרש בו מה יהיה אם יתקיים התנאי וגם מה יהיה אם לא יתקיים התנאי, אם לא כפל את התנאי — \u0003אינו תנאי.\u0004 משמע שהוא סבור שמכלל לאו אי אפשר ללמוד הן, או להיפך.","\u0003אלא\u0004 יש לומר כי משנתנו כשיטת \u0003ר' יהודה היא.\u0004 על כך מקשים: אם כן, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה, \u0003ר' יהודה אומר: האומר \"ירושלים\" לא אמר כלום.\u0004 ונדייק: \u0003מדסיפא\u0004 \u0005[מ\u0006תוך \u0005שבסופה]\u0006 חולק \u0003ר' יהודה —\u0004 משמע ש\u0003רישא לאו\u0004 \u0005[ראשה לא]\u0006 דווקא כשיטת \u0003ר' יהודה היא!\u0004","ודוחים: אפשר לומר כי כל המשנה \u0003כולה\u0004 כשיטת \u0003ר' יהודה היא, והכי קתני\u0004 \u0005[וכך שנה],\u0006 כך צריך להבין את הלשון: כל אלו דברי ר' יהודה, \u0003שר' יהודה אומר\u0004 ומסביר: \u0003האומר \"ירושלים\" — לא אמר כלום,\u0004 כי ביטוי זה אין לו משמעות.","ושואלים: והאם החסרון הוא רק בביטוי \"ירושלים\" כשלעצמו שאין בו קבלת נדר בשלימות, \u0003וכי אמר\u0004 \u0005[וכאשר אומר]\u0006 \u0003\"כירושלים\",\u0004 האם \u0003ל\u0004שיטת \u0003ר' יהודה מי מיתסר\u0004 \u0005[האם נאסר]\u0006 בכך? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: האומר \"כירושלים\" — לא אמר כלום, עד שידור בדבר הקרב בירושלים!\u0004 ואם כן יש לחזור להבנה הפשוטה שר' יהודה חולק על דעת החכם הראשון במשנה!","ודוחים: יש לפרש באופן אחר ולומר כי המשנה \u0003כולה\u0004 שיטת \u0003ר' יהודה היא,\u0004 וכפי שאמרנו קודם. ולענין הסתירה להסבר זה בשיטת ר' יהודה — הרי זו מחלוקת של \u0003תרי תנאי אליבא\u0004 \u0005[שני תנאים על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יהודה,\u0004 שהאחד אומר ש\"כירושלים\" הוא גם לשון נדר, והאחר אומר שאפילו \"כירושלים\" אינה נדר."],["\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 האומר \u0003\"חולין\" \"החולין\" \"כחולין\", בין\u0004 שאמר \u0003\"שאוכל לך\" ובין\u0004 שאמר \u0003\"שלא אוכל לך\",\u0004 בכל אלה — הרי זה \u0003מותר,\u0004 שאין כאן נדר. ואם אמר \u0003\"לחולין שאוכל לך\" — אסור.\u0004 אמר \u0003\"לחולין לא אוכל לך\" — מותר.\u0004","ונברר: \u0003רישא מני\u0004 \u0005[ראשה,\u0006 תחילתה של אותה ברייתא, כשיטת \u0005מי היא] —\u0006 כשיטת \u0003ר' מאיר היא, דלית ליה\u0004 \u0005[שאין לו],\u0006 שאינו מקבל את הסברה ש\u0003מכלל לאו אתה שומע הין,\u0004 ולכן אף אם אמר \"חולין יהא מה שלא אוכל לך\" — לא התכוון לומר שמה שאוכל ממנו יהיה כקודשים.","אולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא ששנינו בה: אם אמר \u0003\"לחולין לא אוכל לך\" — מותר. והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אם אמר \u0003\"לקרבן לא אוכל לך\" ר' מאיר אוסר. וקשיא לן\u0004 \u0005[ו\u0006היה \u0005קשה לנו]:\u0006 \u0003הא לית ליה\u0004 \u0005[הרי אין לו]\u0006 לר' מאיר הסברה ש\u0003מכלל לאו אתה שומע הין,\u0004 ומדוע כשאמר \"לקרבן לא אוכל לך\" נאסר? שהרי הדבר מתפרש כאילו אמר \"לא קרבן (מה) שלא אוכל לך\" ומכאן שמה שיאכל יהא כקרבן, אבל את המסקנה זו המתבססת על \"מכלל לאו אתה שומע הן\" אין ר' מאיר מקבל!","\u0003ו\u0004לתרץ קושי זה \u0003אמר ר' אבא:\u0004 כשהוא אומר בלשון זו, \u0003נעשה כאומר: לקרבן יהא, לפיכך לא אוכל לך.\u0004 ולדרך זו \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 כשאמר \"לחולין לא אוכל לך\" יש לפרש כי \u0003הכי קאמר ליה\u0004 \u0005[כך\u0006 הוא \u0005אומר לו]:\u0006 \u0003לא חולין ליהוי\u0004 \u0005[יהיה]\u0006 דבר זה, אלא קרבן, \u0003לפיכך לא אוכל לך,\u0004 והריהו אסור!","ומתרצים: \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 של הברייתא \u0003סבר לה\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר בחדא\u0004 \u0005[ב\u0006דבר \u0005אחד]\u0006 \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו ב\u0006דבר \u0005אחד];\u0006 כיצד? \u0003סבר לה כותיה בחדא\u0004 \u0005[סובר\u0006 הוא \u0005כמותו ב\u0006דבר \u0005אחד]\u0006 \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003מכלל לאו אתה שומע הין, ופליג עליה בחדא\u0004 \u0005[וחולק עליו ב\u0006דבר \u0005אחד]\u0006 \u0003ב\u0004ענין \u0003קרבן.\u0004 שסבור שגם אם אמר \"לקרבן לא אוכל לך\" אין לפרש כוונתו \"לקרבן יהיה ולפיכך לא אוכל\", אלא צריך שיאמר לשון נדר מפורשת. והוא הדין לאמור בברייתא — אם אמר \"לחולין לא אוכל לך\".","\u0003רב אשי אמר:\u0004 את הסתירה בברייתא אפשר לתרץ לדעת ר' מאיר באופן אחר; \u0003הא דאמר\u0004 \u0005[זה\u0006 כ\u0005שאומר]\u0006 \u0003\"לחולין\" —\u0004 אינו אוסר, שאין בכך לשון נדר, \u0003והא דאמר\u0004 \u0005[וזה\u0006 כ\u0005שאומר]\u0006 \u0003\"לא לחולין\",\u0004 ש\u0003משמע\u0004 בבהירות: \u0003לא ליהוי\u0004 \u0005[יהיה]\u0006 \u0003חולין אלא כקרבן,\u0004 ודבר זה נחשב כדיבור מפורש, אפילו לדברי ר' מאיר.","שנינו במשנה שהאומר \u0003\"טהור\",\u0004 או \u0003\"טמא\",\u0004 או \u0003\"נותר\",\u0004 או \u0003\"פיגול\" — אסור. בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא:\u0004 האומר על דבר מסויים \u0003\"הרי עלי כבשר זבחי שלמים לאחר זריקת דמים\", מהו —\u0004 האם יש כאן נדר אוסר, או לא?","ומקשים: \u0003אי דקאמר בהדין לישנא\u0004 \u0005[אם שאומר בזו הלשון]\u0006 בדיוק — הלא \u0003בהיתרא קא מתפיס\u0004 \u0005[ב\u0006דבר \u0005המותר הריהו מתפיס],\u0006 שהרי בשר זבח שלמים לאחר זריקת הדם על גבי המזבח מותר באכילה, ואם כן אין פה איפוא נדר בדבר שיש בו מעילה ואיסור! \u0003אלא\u0004 צריך לפרש את השאלה בדרך הבאה: \u0003כגון דמחית\u0004 \u0005[שמניח]\u0006 \u0003בשר זבחי שלמים\u0004 לאחר זריקת דמים במקום אחד \u0003ומחית דהיתרא גביה\u0004 \u0005[ומניח\u0006 דבר \u0005של היתר לידו]\u0006 \u0003ואמר: \"זה כזה\",\u0004 אז נשאלת השאלה: \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? מה היתה כוונתו, האם \u0003בעיקרו\u0004 של זבח השלמים \u0003קא מתפיס\u0004 \u0005[הריהו מתפיס],\u0006 שכוונתו שההיתר יהא דינו כשלמים מעיקרם, שהם אסורים בהנאה עד שייזרק הדם, \u0003או בהיתרא קא מתפיס\u0004 \u0005[ב\u0006דבר של \u0005היתר הוא מתפיס]?\u0006 שהרי בשר זבח השלמים המונח לפניו הוא לאחר זריקת הדם ומותר באכילה, ומה שאמר \"זה כזה\" אינו מתפיס דין קרבן עליו.","\u0003אמר רבא\u0004 לפתור את השאלה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנינו במשנתנו: האומר על מאכל שהוא אסור עליו כ\u0003נותר\u0004 או כ\u0003פיגול. —\u0004 הרי זה אסור."],["\u0003והא\u0004 \u0005[והרי]\u0006 \u0003נותר ופיגול לאחר זריקת דמים הוא\u0004 איסורם, ואין בהם אז עוד דין מעילה, אף שהם אסורים מטעם אחר. ואם כן, מוכח מכאן שכאשר הוא מתפיס בדבר — אינו מתפיס במצבו הנוכחי, אלא בעיקרו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן:\u0004 אפשר לומר שמדובר כאן \u0003בנותר של עולה,\u0004 שאין בשרה מותר באכילה לעולם וגם לאחר זריקת הדם עדיין קדושת עולה חלה עליו ולא יצא מקדושתו כלל. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם כן, ליתני\u0004 \u0005[שישנה]\u0006 במפורש שהתפיס \u0003בבשר עולה!\u0004","ודוחים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר]:\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006 המשנה\u0005]\u0006 לומר שאם אמר על דבר \u0003\"\u0004הרי זה כ\u0003בשר עולה\"\u0004 ש\u0003אסור, דהא\u0004 \u0005[שהרי]\u0006 \u0003בקרבן\u0004 ממש \u0003קא\u0004 \u0005[הריהו]\u0006 \u0003מתפיס\u0004 את החפץ, אבל \u0003נותר ופיגול\u0004 של \u0003עולה איצטריכא\u0004 \u0005[הוצרכה\u0006 לומר\u0005],\u0006","כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שכוונתו בנדר היתה שיהא זה \u0003כאיסור נותר,\u0004 או \u0003כאיסור פיגול, והוה ליה\u0004 \u0005[והרי הוא]\u0006 \u0003כמתפיס\u0004 את הנדר \u0003בדבר האסור,\u0004 ולא בדבר הנדור, שרק בו אפשר להתפיס ולאסור דבר אחר, \u0003ו\u0004בנדר כזה \u0003לא מיתסר\u0004 \u0005[אינו נאסר],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכאשר מתפיס בנותר כוונתו היא לעיקרו של דבר, שהוא הקרבן, והוא דבר הנדור.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003איזהו איסר האמור בתורה —\u0004 אם \u0003אמר \"הריני שלא אוכל בשר ושלא אשתה יין\u0004 ביום זה \u0003כיום שמת בו אביו\"\u0004 של הנודר, שהמנהג לצום באותו יום, או \u0003\"כיום שמת בו רבו\"\u0004 שהוא מתאבל עליו כאביו, או \u0003\"כיום שנהרג בו גדליה בן אחיקם\"\u0004 (צום גדליה), או \u0003\"כיום שראיתי ירושלים בחורבנה\", ואמר שמואל: והוא שנדור באותו היום.\u0004 כלומר, שאותו יום שהוא תולה בו את נדרו — הוא עצמו יום שנדר בו שלא יאכל, ולכן תופס נדר בנדר.","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]?\u0006 \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003כגון\u0004 במקרה \u0003דקאי בחד בשבא דמית ביה אבוה\u0004 \u0005[ש\u0006הוא \u0005עומד ב\u0006יום \u0005ראשון בשבת\u0006 שהוא היום בשבוע \u0005שמת בו אביו]\u0006 \u0003ואף על גב דאיכא טובא חד בשבא דהיתרא\u0004 \u0005[ואף על פי שיש\u0006 בינתיים \u0005הרבה\u0006 ימי \u0005ראשון בשבת של היתר],\u0006 ובכל זאת כאשר אומר \"כיום שמת בו אביו\" כוונתו לא לסתם יום ראשון בשבוע, אלא לאותו יום ראשון שמת בו אביו, שבו נדר לצום, \u0003וקתני\u0004 \u0005[ושנה]\u0006 התנא שהוא \u0003אסור. שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003בעיקר הוא מתפיס,\u0004 והוא הדין למתפיס בבשר זבחי שלמים לאחר זריקת דמים.","ודוחים: מה שאמר \u0003שמואל, הכי איתמר\u0004 \u0005[כך נאמר],\u0006 \u0003אמר שמואל: והוא שנדור ובא מאותו היום ואילך.\u0004 כלומר, שבכל יום שהוא יום השנה לאביו נודר שיהיה אסור באכילה. ואם כן כאשר מזכיר ומתפיס ביום זה הריהו מתפיס בדבר הנדור. ואם כן אין מכאן ראיה לענייננו.","\u0003אמר רבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: האומר שדבר זה יהא עליו \u0003\"כחלת אהרן\"\u0004 שמפרישים מן העיסה לכהן, או \u0003\"כתרומתו\"\u0004 שמפרישים לו מן התבואה — \u0003מותר,\u0004 כי דברים אלה אסורים באכילה לזרים, שאינם כהנים, ונחשב כמתפיס בדבר האסור, שאין בכך כלום. ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה אומר \u0003\"כתרומת לחמי תודה\",\u0004 אף שגם הם נאכלים רק לכהנים ואסורים לזרים, כיון שעיקרם קרבן — \u0003אסור;\u0004"],["\u0003והא\u0004 \u0005[והרי]\u0006 \u0003תרומת לחמי תודה לאחר זריקת דמים היא,\u0004 שהרי רק אז מותרים הם באכילה לכהנים, ומשמע שכאשר הוא מתפיס — בעיקרו של האיסור הוא מתפיס, ולא במצבו הנוכחי.","ודוחים: אל תדקדק מן הברייתא שאם אמר \"כתרומת לחמי תודה\" הוא שאסור, אלא \u0003אימא\u0004 \u0005[אמור]\u0006 שיש לדייק משם שאם אמר \u0003\"כתרומת הלשכה\",\u0004 כלומר, כשקלים שהיו תורמים למקדש — \u0003אסור,\u0004 ולתרומה זו לא היה היתר מעולם.","ושואלים: אם כן, \u0003אבל\u0004 אם התפיס ב\u0003תרומת לחמי תודה מאי\u0004 \u0005[מה]\u0006 לדעתך יהא הדין — \u0003מותר?\u0004 אם כן, \u0003ליתני\u0004 \u0005[שישנה]\u0006 באותה משנה \u0003\"\u0004תרומת \u0003לחמי תודה\"\u0004 מותר, למרות שתחילתה בדבר הנדור, \u0003ו\u0004אנו נלמד מכאן כי \u0003כל שכן\u0004 שיהא מותר אם מתפיס ב\u0003תרומתו\u0004 שאינה אלא דבר האסור! ודוחים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 שגם \u0003תרומת לחמי תודה\u0004 כיון שגם היא ניתנת לכהן — \u0003תרומתו היא\u0004 נקראת, ואין לחלק בין תרומה זו לבין תרומה אחרת.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאפשר לומר כהסבר הקודם ולדייק שהאומר \"כתרומת לחמי תודה\" — אסור. אולם, \u0003תרומת לחמי תודה נמי\u0004 \u0005[גם כן]\u0006 מדובר \u0003קודם זריקת דמים הוא.\u0004 וכיצד ייתכן שתהא תרומה זו מופרשת עוד לפני זריקת הדמים — \u0003כגון דאפרשינהו\u0004 \u0005[שהפריש אותם],\u0006 את הלחמים שרוצה לתת לכהן כבר \u0003ב\u0004זמן \u0003לישה\u0004 של הלחמים.","\u0003וכי הא\u0004 \u0005[וכמו זו]\u0006 ש\u0003אמר רב טובי בר קיסנא אמר שמואל: לחמי תודה שאפאן בארבע חלות\u0004 ולא עשה אותם כרגיל ארבעים חלות — \u0003יצא.\u0004 ושאלו על דבריו: \u0003והכתיב\u0004 \u0005[והרי כתוב]\u0006 שצריך להביא \u0003ארבעים\u0004 חלות, עשרה מכל סוג! והשיבו: ארבעים שנאמרו הם \u0003למצוה,\u0004 שכך צריך לעשות לכתחילה. אבל אם הוא עושה רק ארבע, אחת מכל סוג — יצא.","ועוד שאלו: \u0003והא בעי למשקל\u0004 \u0005[והרי צריך ליטול,\u0006 להפריש\u0005]\u0006 מן הלחמים הללו אחד מכל עשרה \u0003תרומה\u0004 לכהן! \u0003וכי תימא דשקיל חדא ריפתא על כולה\u0004 \u0005[ואם תאמר ש\u0006הוא \u0005נוטל לחם אחד על כולם]\u0006 שעושה ארבעה לחמים, אחד מכל סוג, ונותן אחד מהם לכהן — \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 על מה שנאמר \"והקריב ממנו \u0003אחד מכל קרבן\u0004 תרומה לה' לכהן... יהיה\" (ויקרא ז, יד) ולמדו מכאן \u0003שלא יטול מקרבן על חבירו,\u0004 וכיון שיש ארבעה סוגים שונים שמביא כלחמי תודה, אינו יכול לתת ממין אחד על השני! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003דשקיל\u0004 \u0005[שלוקח]\u0006 ונותן לכהן \u0003פרוסה מכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מארבעת הלחמים, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 נאמר \u0003\"אחד\"\u0004 (ויקרא ז, יד), וכוונתו \u0003שלא יטול פרוסה,\u0004 אלא לחם שלם!","\u0003אלא\u0004 בהכרח יש לומר \u0003דאפרשינהו\u0004 \u0005[שהפריש אותם]\u0006 את הלחמים שנותן לכהן כבר \u0003ב\u0004זמן ה\u0003לישה.\u0004 כיצד? \u0003דשקיל\u0004 \u0005[שנוטל]\u0006 תרומה בזמן הלישה, \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003מחמץ, וחדא\u0004 \u0005[ואחת]\u0006 \u0003מן חלות, וחדא\u0004 \u0005[ואחת]\u0006 \u0003מן רקיקים, וחדא\u0004 \u0005[ואחת]\u0006 \u0003מן רבוכה.\u0004 שעושה מכל מין חלה גדולה לעצמו ומפריש ממנה בזמן הלישה חלה קטנה כדי עשירית, והיא תרומה לכהן. ואם כן מוכח מכאן שיש דרך להפריש תרומת לחמי תודה בזמן לישה, ואפשר איפוא להסביר גם לענייננו שמדובר בתרומה כזו שנעשתה בזמן הלישה קודם זריקת דמים, ואין לדייק מכאן שהמתפיס — בעיקרו של הקרבן מתפיס.","ומנסים להציע: \u0003לימא\u0004 \u0005[נאמר]\u0006 כי בעיה זו, אם מתפיס בעיקרו או במצבו הנוכחי \u0003כתנאי\u0004 \u0005[\u0006היא \u0005כ\u0006מחלוקת \u0005תנאים],\u0006 שכבר נחלקו בבעיה זו; ששנינו: האומר \u0003\"הרי עלי כבכור\", ר' יעקב אוסר, ור' יהודה מתיר.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שמתפיס בבכור \u0003לפני זריקת דמים — מאי טעמא דמאן דשרי\u0004 \u0005[מה הטעם של מי שמתיר],\u0006 שהרי הבכור הזה קדוש. \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003לאחר זריקת דמים — מאי טעמא דמאן דאסר\u0004 \u0005[מה הטעם של מי שאוסר]?\u0006 שהרי לאחר זריקת הדם הוא רכוש הכהן. \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר כאן"],["\u0003דמחית\u0004 \u0005[שמניח]\u0006 \u0003בשר בכור ומחית\u0004 \u0005[ומניח]\u0006 \u0003בשר דהאיך גביה\u0004 \u0005[אחר לידו]\u0006 \u0003ואמר\u0004 על הבשר השני \u0003\"זה כזה\",\u0004 והשאלה היתה האם משמעות הנדר היא להתפיס בעיקרו של הבכור שהוא כדבר הנדור, או להתפיס במצבו הנוכחי שעכשיו הוא רכוש הכהן. \u0003ו\u0004אם כן \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה.","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 מדובר כאן \u0003לפני זריקת דמים, ומאי טעמא דמאן דשרי\u0004 \u0005[ומה הטעם של מי שמתיר]\u0006 — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"כי ידר\"\u0004 (במדבר ל, ג), וכוונתו: \u0003עד שידור בדבר הנדור,\u0004 כלומר, שיתלה נדרו בדבר שנאסר על ידי נדר, \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003בכור\u0004 ש\u0003דבר האסור הוא\u0004 ואינו דבר הנדור, שהרי קדושתו של הבכור אינה באה מכוח נדר, אלא מכוח היוולדו ראשון לאמו.","\u0003ומאן דאסר\u0004 \u0005[ומי שאוסר]\u0006 סבור כי מה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לה'\"\u0004 (במדבר ל, ג) בא \u0003לרבות\u0004 כל \u0003דבר האסור.\u0004","ושואלים: \u0003ומאן דשרי\u0004 \u0005[ומי שמתיר]\u0006 בבכור, את המלה \u0003\"לה'\" מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה לו],\u0006 מה הוא למד מהמלה הזו? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרכה לו]\u0006 מלה זו \u0003למתפיס בחטאת ואשם,\u0004 שאף שגם בהם צד חובה ולא של נדר, שהרי חייב להביאם ואינם רשות, מכל מקום יכול להתפיס בהם נדר.","ושואלים: \u0003ומה ראית לרבות\u0004 דווקא \u0003חטאת ואשם ולהוציא את הבכור?\u0004 ומשיבים: \u0003מרבה אני חטאת ואשם שהוא מתפיס\u0004 קדושה בבהמה \u0003בנדר,\u0004 שאומר \"הרי זו לחטאתי (לאשמי)\", \u0003ומוציא אני את הבכור שהוא קדוש ממעי אמו.\u0004","\u0003ומאן דאסר\u0004 \u0005[ומי שאוסר]\u0006 סבור כי \u0003בכור נמי\u0004 \u0005[גם כן]\u0006 \u0003מתפיסו בנדר הוא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003משום רבי אמרו: מנין ל\u0004זה ש\u0003נולד\u0004 לו \u0003בכור\u0004 בהמה \u0003בתוך ביתו שמצוה\u0004 בכל זאת \u0003להקדישו — שנאמר: \"הזכר תקדיש\"\u0004 (דברים טו, יט), שאף שיש בו קדושה מלידה, מכל מקום מצווה בעליו להקדיש אותו במפורש, ואם כן יש בו צד של נדר.","ומסבירים: \u0003ומאן דשרי\u0004 \u0005[ומי שמתיר]\u0006 בבכור, אומר כי אף שמצווה להקדישו, מכל מקום \u0003כי לא מקדיש ליה מי לא מיקדיש\u0004 \u0005[כאשר אינו מקדיש אותו האם איננו מקודש]?\u0006 ומכאן שעיקר קדושתו לא מחמת הנדר היא באה, אלא מחמת עצמו.","שנינו במשנה שהאומר \u0003\"כאימרא\",\u0004 או \u0003\"כדירים\"\u0004 — הרי זה נדר.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 האומר לחבירו \u0003\"אימרא\",\u0004 או \u0003\"לאימרא\",\u0004 או \u0003\"כאימרא\",\u0004 או שאומר \u0003\"דירים\",\u0004 או \u0003\"לדירים\" \"כדירים\",\u0004 או אומר \u0003\"עצים\",\u0004 או \u0003\"לעצים\",\u0004 או \u0003\"כעצים\",\u0004 או \u0003\"אישים\",\u0004 או \u0003\"לאישים\",\u0004 או \u0003\"כאישים\",\u0004 או \u0003\"מזבח\",\u0004 או \u0003\"למזבח\",\u0004 או \u0003\"כמזבח\",\u0004 או אמר \u0003\"היכל\",\u0004 או \u0003\"להיכל\",\u0004 או \u0003\"כהיכל\",\u0004 או \u0003\"ירושלים\",\u0004 או \u0003\"לירושלים\",\u0004 או \u0003\"כירושלים\",\u0004 ב\u0003כולן\u0004 אם הוסיף ואמר \u0003\"שאוכל לך\" — אסור.\u0004 שכוונתו שמה שאוכל משלו יהיה אסור עליו כדבר הקדוש. ואם הוסיף ואמר לאחר כל אחד מביטויים אלה \u0003\"לא אוכל לך\" — מותר,\u0004 שאין משמע מדבריו אלא שמה שלא יאכל יהיה אסור.","ושואלים: \u0003מאן שמעינן ליה דלא שני ליה\u0004 \u0005[מיהו\u0006 החכם ש\u0005שמענו אותו שאין משנה לו]\u0006 אם אמר \u0003\"אימרא\"\u0004 או \u0003\"לאימרא\"\u0004 או \u0003\"כאימרא\"\u0004 והוסיף \"שאוכל לך\" — \u0003ר' מאיר היא.\u0004 שאילו לר' יהודה צריך לומר דווקא \"כאימרא\".","אולם אם כן, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא: \u0003וכולן\u0004 אם אמר \u0003\"לא אוכל לך\" — מותר. והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אם אמר \u0003\"לקרבן לא אוכל לך\" ר' מאיר אוסר, ואמר ר' אבא\u0004 הסבר לשיטת ר' מאיר: \u0003נעשה כאומר \"לקרבן יהא לפיכך לא אוכל לך\".\u0004 הרי שלדעת ר' מאיר אין הבדל אם אמר \"אוכל\" או \"לא אוכל\"!","ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה,\u0006 בברייתא\u0005]\u0006 מדובר ש\u0003אמר\u0004 בלשון \u0003\"לא לאימרא\"\u0004 (\"לאימרא\") ואז כוונתו שמה שלא יאכל משלו אינו כקרבן. ואף שאפשר היה להסיק מכאן (בדרך מכלל לאו אתה שומע הן) שמה שיאכל משלו יהיה כקרבן, הרי כבר אמרנו כי ר' מאיר אינו למד הן מכלל לאו. \u0003הא\u0004 \u0005[זה,\u0006 במשנה\u0005]\u0006 מדובר ש\u0003אמר \"לאימרא\"\u0004 יש בכך צד של הקדש, שכן אז מפרשים את דבריו כאילו אמר: לאימרא יהא, לפיכך לא אוכל.","\u0003האומר \"קרבן\",\u0004 או \u0003\"עולה\",\u0004 או \u0003\"מנחה\",\u0004 או \u0003\"חטאת\",\u0004 או \u0003\"תודה\",\u0004 או \u0003\"שלמים\",\u0004 והוסיף בכולם \u0003\"שאני אוכל לך\" — אסור. ר' יהודה מתיר\u0004 בכל אלה. האומר \u0003\"הקרבן\",\u0004 או \u0003\"כקרבן\",\u0004 או \u0003\"קרבן שאוכל לך\" — אסור.\u0004 ואם אומר \u0003\"לקרבן לא אוכל לך\" — ר' מאיר\u0004 הוא ה\u0003אוסר\u0004 בזה.","\u0003קתני\u0004 \u0005[שנה\u0006 במשנה\u0005]:\u0006 אם אמר \u0003\"קרבן\",\u0004 או \u0003\"הקרבן\",\u0004 או \u0003\"כקרבן שאוכל לך\" — אסור.\u0004 ומכאן יש להסיק כי \u0003סתמא תנא\u0004 \u0005[סתמה\u0006 של משנה זו \u0005שנה]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר, דלא שני ליה\u0004 \u0005[שאין משנה לו]\u0006 \u0003בין\u0004 אומר \u0003\"אימרא\"\u0004 לאומר \u0003\"לאימרא\"\u0004","ושואלים: אולם \u0003[אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' מאיר\u0004 היא — \u0003הא\u0004 \u0005[זו]]\u0006 \u0003דקתני\u0004 \u0005[ששנינו]\u0006 בהמשך המשנה \u0003\"הקרבן שאוכל לך\" אסור, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מודים חכמים\u0004 (כלומר, הדעה המובאת במשנה בסתם) \u0003לר' יהודה באומר \"הא קרבן\",\u0004 או \u0003\"הא עולה\",\u0004 או \u0003\"הא מנחה\",\u0004 או \u0003\"הא חטאת שאוכל לך\" — שמותר,\u0004 ומדוע? \u0003שלא נדר זה\u0004 שהדבר שהוא אוסר אותו יהיה כקרבן, \u0003אלא\u0004 שנדר \u0003בחיי קרבן,\u0004 ושמלה זו \"הא קרבן\" היא כמלת קריאה בלבד, ולא היתה כאן התפסת נדר בדבר הנדור, ואין בו איסור!"],["\u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמותר — כש\u0003אמר \"הא קרבן\" והא\u0004 \u0005[וזה]\u0006 שאסור — כש\u0003אמר \"הקרבן\"\u0004. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 כשאומר \"הא קרבן\" אינו אסור — משום ש\u0003חיי קרבן קאמר\u0004 \u0005[אומר]\u0006 ואין כאן נדר.","\u0003קתני\u0004 \u0005[שנינו]:\u0006 \u0003\"לקרבן לא אוכל לך\", ר' מאיר אוסר.\u0004 והבינו כי משמעות הנדר היא: לא קרבן יהיה מה שלא אוכל לך, ומכאן נובע כי מה שאוכל — יהא כקרבן, והרי זה נדר. ושואלים: \u0003והא לית ליה\u0004 \u0005[והרי אין לו]\u0006 \u0003לר' מאיר,\u0004 שאינו מקבל את הסברה של \u0003מכלל לאו אתה שומע הן!\u0004 ומדוע נאסר כשאומר כך? \u0003אמר ר' אבא:\u0004 יש להבין באופן אחר, שהאומר כך \u0003נעשה כאומר: לקרבן יהא, לפיכך לא אוכל לך.\u0004 ולכן הוא נאסר, ואין כאן צורך ללמוד מכלל לאו הן.","\u0003האומר לחבירו \"קונם פי מדבר עמך\",\u0004 או \u0003\"\u0004קונם \u0003ידי עושה עמך\",\u0004 או \u0003\"\u0004קונם \u0003רגלי מהלכת עמך\" — אסור,\u0004 שהטיל נדר על האבר, ומשום כך נאסר.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: יש צד של \u0003חומר\u0004 (חומרה) \u0003בשבועות מבנדרים ו\u0004יש חומר \u0003בנדרים מבשבועות;\u0004 כיצד? \u0003חומר בנדרים — שהנדרים חלים על המצוה כברשות, מה שאין כן בשבועות\u0004 שאין אדם יכול להישבע על המצווה לבטלה. \u0003וחומר בשבועות — שהשבועות חלות על דבר שיש בו ממש ושאין בו ממש, מה שאין כן בנדרים.\u0004 וכיצד אם כן אמרו במשנה שיכול להטיל איסור נדר על דיבור או על מעשה, שהוא דבר שאין בו ממש?","\u0003אמר רב יהודה: באומר \"יאסר פי לדיבורי\",\u0004 או \u0003\"ידי למעשיהם\",\u0004 או \u0003\"רגלי להילוכן\",\u0004 כלומר, שלא הטיל איסור על המעשה, אלא הטיל איסור על האבר העושה את המעשה. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 לפרש כך, \u0003דקתני\u0004 \u0005[ששנינו]\u0006 \u0003\"פי מדבר עמך\", ולא קתני\u0004 \u0005[שנינו]\u0006 שהוא נודר \u0003\"שאני מדבר עמך\",\u0004 משמע שהחיל את הנדר לא על הפעולה אלא על האבר, ונדר זה בוודאי חל.","","\u0003ואלו\u0004 הנדרים שהם \u0003מותרין,\u0004 שאף שאומרם בלשון נדר אין הם נחשבים לנדר: אם אומר \u0003\"חולין\u0004 עלי מה \u0003שאוכל לך\",\u0004 או \u0003\"כבשר חזיר\u0004 שאוכל לך \u0003\",\u0004 או \u0003\"כעבודה זרה\",\u0004 או \u0003\"כעורות לבובין\"\u0004 (עורות של בהמות שהוציאו מהן את הלב לעבודה זרה, שהם אסורים בהנאה משום תקרובת עבודה זרה), או \u0003\"כנבילות וטריפות\",\u0004 או \u0003\"כשקצים ורמשים\",\u0004 או \u0003\"כחלת אהרון וכתרומתו\" —\u0004 בכל אלה \u0003מותר.\u0004 שאף שדברים אלה שהזכיר אסורים באכילה, כיון שאין איסורם בא מחמת נדר, משום כך אי אפשר להתפיס בהם נדר אחר.","\u0003האומר לאשתו \"הרי את עלי כאימא\",\u0004 וכשם שאני אסור לבוא על אמי כך את אסורה עלי בהנאה — \u0003פותחין לו פתח ממקום אחר.\u0004 כלומר, אף שנדר זה באמת אינו נדר, שהרי התפיס בדבר האסור ולא בדבר הנדור, אין אומרים לו שהוא מותר, אלא נוהגים כאילו היה זה נדר ממש, ומתירים אותו על ידי שמוצאים לו דרך (\"פתח\") היתר מצד אחר, כדי \u0003שלא יקל ראשו ל\u0004עשות \u0003כך,\u0004 ולא יבוא לזלזל בנדרים שיש בהם ממש.","ומדייקים מלשון המשנה: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר \"חולין שאוכל לך\"\u0004 הרי זה מותר, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אמר \"לחולין שאוכל לך\", משמע: לא לחולין ליהוי\u0004 \u0005[יהיה]\u0006 \u0003אלא קרבן,\u0004 ומכלל הדברים עולה שזהו ביטוי של נדר.","ונברר: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי היא משנתנו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא כדעת \u0003ר' מאיר — הא לית ליה\u0004 \u0005[הרי אין לו]\u0006 אינו מקבל את הסברה של \u0003מכלל\u0004"]]};
